FAMILY_CANDIDATES = {
    "mouse": "MOUSE_PRODUCTS_DATA",
    "keyboard": "KEYBOARD_PRODUCTS_DATA",
    "audio": "AUDIO_PRODUCTS_DATA",
    "gamepad": "GAMEPAD_PRODUCTS_DATA",
    "system": "SYSTEM_PRODUCTS_DATA",
    "accessories": "ACCESSORY_SYSTEM_PRODUCTS_DATA",
}
# Batch families share these limits: adding families must not multiply analyzer
# processes or simultaneous full resource crawls.
ACQUISITION_SLOTS = threading.BoundedSemaphore(6)
ANALYSIS_SLOTS = threading.BoundedSemaphore(2)


def bounded_call(slots, callback, *args):
    with slots:
        return callback(*args)


def identity(path):
    return {"path": a.rel(path), "bytes": path.stat().st_size, "sha256": a.sha(path)}


def valid(row):
    path = a.ROOT / row.get("path", "")
    return path.is_file() and path.stat().st_size == row.get("bytes") and a.sha(path) == row.get("sha256")


def pinned_resources(acquisition, requests, mappings=None):
    """Verify display aliases and converted pixels against the pinned lock.

    Same-format originals must equal the pinned bytes, allowing only the lock's
    explicit LF to CRLF proof. Converted media (AVIF to PNG, CSS data URIs)
    loads only its pinned output and compares all decoded RGBA pixels.
    """
    mappings = resource_sources.load_resource_mappings(root=a.ROOT) if mappings is None else mappings
    receipt = json.loads((a.ROOT / acquisition).read_bytes())
    originals = {row.get("path"): row for row in receipt.get("files", [])}
    lock = resource_sources.validate_lock(json.loads((a.ROOT / resource_sources.LOCK).read_bytes()))
    pinned = {row["path"]: row for row in lock["git_files"]}
    pinned.update({row["path"]: row for group in lock["groups"] for row in group["files"]})
    verified = []
    for source_name, values in requests.items():
        source_row = originals.get(source_name)
        if not source_row or source_row.get("http_status") != 200 or not valid(source_row):
            raise ValueError("Resource acquisition bytes do not verify: " + source_name)
        content = (a.ROOT / source_name).read_bytes()
        for request in (values if isinstance(values, list) else [values]):
            request = request if isinstance(request, dict) else {"display": request}
            display = request["display"]
            paths = {row["path"] for table in mappings["tables"] for row in table["entries"] if row["key"] == display}
            if len(paths) != 1 or next(iter(paths)) not in pinned:
                raise ValueError("Display alias has no unique pinned resource: " + display)
            locked = pinned[next(iter(paths))]
            same_format = (Path(source_name).suffix.lower() == Path(display).suffix.lower()
                           and "inline_css_png" not in request)
            entry = {"display": display, "source": source_name, "source_sha256": source_row["sha256"],
                     "output": locked["path"], "output_sha256": locked["sha256"], "output_bytes": locked["bytes"],
                     "resource_revision": lock["storage"]["revision"]}
            if same_format:
                try:
                    proof = resource_sources.verified_alias_reuse(content, display, root=a.ROOT, mappings=mappings)
                except ValueError:
                    proof = resource_sources.verified_alias_reuse(content, display, normalize_source_lf=True,
                                                                  root=a.ROOT, mappings=mappings)
                entry["locked_alias_reuse"] = proof
            else:
                import workspace
                entry["conversion"] = ("inline CSS PNG " + request["inline_css_png"]["sha256"]
                                       if "inline_css_png" in request else
                                       Path(source_name).suffix.lower() + " to " + Path(display).suffix.lower())
                proof = workspace.verify_pinned_resource_conversion(source_row, request, locked, lock["storage"])
                entry["conversion_verification"] = proof
                entry["conversion_rechecked"] = proof["passed"]
            verified.append(entry)
    return verified


def candidates(path):
    rows = json.loads(path.read_bytes())
    ids = sorted({row["product_id"] for row in rows})
    if any(type(pid) is not int or pid <= 0 for pid in ids):
        raise ValueError("Product candidates must be positive integer IDs")
    return ids




def family_candidate_scope(family):
    """Union every registered product locator with the existing family locators.

    Registry IDs/categories locate official endpoints only. Its historical
    navigation, names and evidence references cannot supply current semantics.
    """
    scopes = {name: set(candidates(a.builtin_data_path("razer-pages", source)))
              for name, source in FAMILY_CANDIDATES.items()}
    existing = set().union(*scopes.values())
    registry = a.ROOT / resource_database.PRODUCT_REGISTRY
    registry_inputs = [identity(registry)]
    registered = {}
    for product in resource_database.product_registry():
        pid = product["id"]
        categories = product["categories"]
        registered[pid] = categories
        if pid in existing:
            continue
        if "MOUSE" in categories:
            owner = "mouse"
        elif any(category in {"KEYBOARD", "KEYPAD"} for category in categories):
            owner = "keyboard"
        elif any(category.startswith("AUDIO") for category in categories):
            owner = "audio"
        elif "SYSTEM" in categories:
            owner = "system"
        elif any(category in {"GAMEPAD", "CONTROLLER"} for category in categories):
            owner = "gamepad"
        else:
            owner = "accessories"
        scopes[owner].add(pid)
    if not registered:
        raise ValueError("No product IDs were found in the complete registry locator")
    retained_endpoints = {}
    for owner in scopes:
        retained = set()
        for receipt in (a.ROOT / ".analysis/inputs/frontend").glob(owner + "-*-current/acquisition.json"):
            match = re.fullmatch(re.escape(owner) + r'-(\d+)-current', receipt.parent.name)
            if match:
                retained.add(int(match[1]))
        scopes[owner].update(retained)
        retained_endpoints[owner] = sorted(retained)
    return sorted(scopes[family]), {
        "registry_locator": identity(registry), "registered_products": len(registered),
        "registry_source_inputs": registry_inputs,
        "family_locator_union": len(existing), "expanded_union": len(set().union(*scopes.values())),
        "products_added_from_registry": sorted(set(registered) - existing),
        "retained_endpoint_locators": retained_endpoints[family],
        "endpoint_identity_policy": "Keep acquired endpoints searchable even when their declared product identity excludes them from the production registry",
        "usage": "IDs/categories locate current official inputs only; implementation evidence must be acquired and verified separately",
    }


def route_evidence():
    import evidence
    import importlib.metadata
    import sys
    sys.path.insert(0, str(Path(__file__).resolve().parent / "analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript

    source = a.ROOT / ".analysis/inputs/frontend/synapse-dashboard-current"
    receipt = source / "acquisition.json"
    acquisition = json.loads(receipt.read_bytes())
    if not acquisition.get("source_current_during_acquisition"):
        raise ValueError("Dashboard route provenance lacks a stable deployment receipt")
    deployment = evidence.frontend_deployment_sources(acquisition)
    if not deployment["entry_original"] or any(
        row["kind"] in {"deployment_stability_identity_mismatch", "deployment_manifest_invalid",
                        "manifest_entrypoint_missing_from_html", "deployment_entry_redirect_outside_origin"}
        for row in deployment["failures"]
    ):
        raise ValueError("Dashboard route deployment identity is not established")
    parser = Parser(Language(tree_sitter_javascript.language()))
    routes = []
    for selected in deployment["sources"]:
        row = selected.get("original")
        if not row or not Path(row["path"]).name.startswith("App.") or not row["path"].endswith(".js"):
            continue
        if not selected["identity_verified"] or not valid(row):
            raise ValueError("Dashboard route input byte identity differs")
        raw = (a.ROOT / row["path"]).read_bytes()
        tree = parser.parse(raw)
        if tree.root_node.has_error:
            raise ValueError("Current Dashboard route original has an AST error")
        pending = [tree.root_node]
        while pending:
            node = pending.pop()
            pending.extend(reversed(node.named_children))
            if node.type != "template_string":
                continue
            literal = raw[node.start_byte:node.end_byte]
            if b"/synapse/products/${" not in literal or b"/ui/index.html" not in literal:
                continue
            owner = node.parent
            while owner is not None and owner.type not in {
                "arrow_function", "function_expression", "function_declaration", "method_definition"
            }:
                owner = owner.parent
            if owner is None:
                raise ValueError("Dashboard product route lacks a complete callable owner")
            body = raw[owner.start_byte:owner.end_byte]
            routes.append({**row, "url": selected["url"], "references": selected["references"],
                           "character_offset": len(raw[:node.start_byte + literal.index(b"/synapse/products/${")].decode("utf-8")),
                           "route": {"byte_start": node.start_byte, "byte_end": node.end_byte,
                                     "body": literal.decode("utf-8")},
                           "owner": {"node_type": owner.type, "byte_start": owner.start_byte,
                                     "byte_end": owner.end_byte, "body": body.decode("utf-8"),
                                     "sha256": hashlib.sha256(body).hexdigest()}})
    if not routes:
        raise ValueError("No current Dashboard product route has a complete callable owner")
    return {"routes": routes, "acquisition": a.rel(receipt), "acquisition_identity": identity(receipt),
            "entry_original": deployment["entry_original"], "manifests": deployment["manifests"],
            "deployment_failures": deployment["failures"],
            "retained_without_current_reference": deployment["retained_without_current_reference"],
            "parsers": {name: importlib.metadata.version(name)
                        for name in ("tree-sitter", "tree-sitter-javascript")},
            "scope": "official product UI entry locator; not product branch semantics"}


def rows_for_index(rows, receipt):
    indexed, responses = [], {}
    receipt = a.resolve(a.rel(receipt), ".analysis/inputs/frontend")
    for row in rows:
        if "path" in row:
            indexed.append({**{key: row[key] for key in ("path", "bytes", "sha256", "url", "acquired_at_utc")},
                            "kind": "official_frontend_artifact"})
            proof = row.get("current_http_revalidation")
            if proof is None:
                continue
            attempts = proof.get("attempts") if isinstance(proof, dict) else None
            if not isinstance(attempts, list) or len(attempts) < 2:
                raise ValueError("Frontend revalidation requires two retained official responses")
            parsed = urllib.parse.urlsplit(row["url"])
            if parsed.scheme != "https" or parsed.netloc != "apps.razer.com":
                raise ValueError("Frontend revalidation requires its official HTTPS source")
            source = a.resolve(row["path"], ".analysis/inputs/frontend")
            retained = []
            for attempt in attempts:
                if (not isinstance(attempt, dict) or attempt.get("url") != row["url"]
                        or attempt.get("final_url") != row["url"]
                        or attempt.get("http_status") != 200 or attempt.get("status") != 200
                        or attempt.get("matches_retained") is not True
                        or any(attempt.get(key) != row[key] for key in ("bytes", "sha256"))
                        or not isinstance(attempt.get("acquired_at_utc"), str) or not attempt["acquired_at_utc"]
                        or not isinstance(attempt.get("path"), str)):
                    raise ValueError("Frontend revalidation response does not verify against its original")
                path = a.resolve(attempt["path"], ".analysis/inputs/frontend")
                if path == source or not path.is_relative_to(receipt.parent):
                    raise ValueError("Frontend revalidation response is outside its acquisition owner")
                claim = {**{key: attempt[key] for key in ("path", "bytes", "sha256", "url", "acquired_at_utc")},
                         "kind": "official_frontend_artifact", "revalidation_of": row["path"],
                         "acquisition_receipt": a.rel(receipt)}
                previous = responses.get(claim["path"])
                if previous and any(previous[key] != claim[key] for key in (
                        "bytes", "sha256", "url", "revalidation_of", "acquisition_receipt")):
                    raise ValueError("Frontend revalidation response has conflicting source owners")
                responses[claim["path"]] = claim
                retained.append(claim)
            a.verify_source_rows([row, *retained])
    indexed.extend(responses.values())
    indexed.append({**identity(receipt), "kind": "acquisition_receipt"})
    return indexed


def index_rows(rows, receipt):
    a.index_files(rows_for_index(rows, receipt))


def publish_frontend_acquisition(receipt, data=None, *, reason="Publish supplemental frontend acquisition with its complete source index"):
    """Keep a completed receipt mutation and its full verified input index together."""
    import evidence
    receipt = a.resolve(a.rel(receipt), ".analysis/inputs/frontend")
    retained = json.loads(receipt.read_bytes()) if data is None else data
    if not isinstance(retained.get("files"), list) or not retained["files"]:
        raise ValueError("Frontend publication has no retained acquisition files")
    originals = [row for row in retained["files"] if "path" in row]
    a.verify_source_rows(originals)
    files = {row["url"]: row for row in originals}
    parsed_entry = urllib.parse.urlsplit(retained.get("entry_url", ""))
    if parsed_entry.scheme != "https" or parsed_entry.netloc != "apps.razer.com":
        raise ValueError("Frontend publication requires its official application entry")
    for claim in retained.get("stability", []):
        original = files.get(claim.get("url"))
        if claim.get("unchanged") is True and (original is None or
                claim.get("before_sha256") != original["sha256"] or
                claim.get("after_sha256") != original["sha256"]):
            raise ValueError("Frontend publication stability claim differs from retained original bytes")
    if retained.get("source_current_during_acquisition") is True and (
            not retained.get("stability") or any(row.get("unchanged") is not True for row in retained["stability"])):
        raise ValueError("Frontend publication claims current bytes without stable deployment roots")
    deployment = evidence.frontend_deployment_sources(retained)
    invalid = {"deployment_original_invalid", "deployment_manifest_invalid", "deployment_entry_redirect_outside_origin",
               "duplicate_acquisition_url", "deployment_stability_identity_mismatch"}
    if deployment["entry_original"] is None or any(row["kind"] in invalid for row in deployment["failures"]):
        raise ValueError("Frontend publication deployment roots or manifests are invalid")
    verification = {"all_retained_bytes_verified": True, "files": len(originals),
        "entry_original": deployment["entry_original"], "manifests": deployment["manifests"],
        "stability": retained.get("stability", []),
        "source_current_during_acquisition": retained.get("source_current_during_acquisition", False),
        "declared_references_fetched": retained.get("declared_references_fetched", False),
        "deployment_failures": deployment["failures"], "reference_gaps": frontend_reference_gaps(retained),
        "source_semantics_complete": False, "network_requests": False}
    indexed = rows_for_index(retained["files"], receipt)
    verification["retained_http_response_aliases"] = sum("revalidation_of" in row for row in indexed)
    if data is not None:
        a.save(receipt, retained)
        indexed[-1] = {**identity(receipt), "kind": "acquisition_receipt"}
    a.index_files(indexed,
        publication={"owner": "tools/families.py", "receipt": a.rel(receipt), "reason": reason,
                     "verification": verification})
    return verification


def save_matrix(path, matrix):
    # A selected-product probe must not erase the rest of the family. Merge
    # only fields this worker changed, under an OS lock shared across processes.
    with a.index_lock(path.with_suffix(".lock")):
        latest = json.loads(path.read_bytes()) if path.is_file() else {}
        retained = {row["product_id"]: row for row in latest.get("products", [])}
        baseline = matrix.get("_baseline_rows", {})
        for row in matrix["products"]:
            pid = row["product_id"]
            previous = baseline.get(pid, {})
            merged = retained.get(pid, {}).copy()
            for field, value in row.items():
                if field not in merged or (field in previous and previous[field] != value):
                    merged[field] = value
                elif pid in baseline and field not in previous:
                    merged[field] = value
            row.clear()
            row.update(merged)
            retained[pid] = row
        owned = {row["product_id"]: row for row in matrix["products"]}
        matrix["products"] = [owned.get(pid, retained[pid]) for pid in sorted(retained)]
        _save_matrix(path, matrix)
        matrix["_baseline_rows"] = deepcopy(retained)


def _save_matrix(path, matrix):
    products = matrix["products"]
    matrix["recorded_at_utc"] = a.stamp()
    matrix["summary"] = {
        "products": len(products),
        "probed": sum("probe" in row for row in products),
        "entries_available": sum(row.get("probe", {}).get("entry_available", False) for row in products),
        "acquired": sum(row.get("acquisition", {}).get("completed", False) for row in products),
        "acquisition_runs_finished": sum(row.get("acquisition", {}).get("run_finished", False) for row in products),
        "analyzed": sum(row.get("analysis", {}).get("completed", False) for row in products),
        "analysis_runs_finished": sum(row.get("analysis", {}).get("run_finished", False) for row in products),
        "retained_files": sum(row.get("acquisition", {}).get("retained_files", 0) for row in products),
        "retained_bytes": sum(row.get("acquisition", {}).get("bytes", 0) for row in products),
        "semantic_audit_completed": sum(row.get("semantic_audit") == "complete" for row in products),
        "implementation_acceptance_completed": sum(row.get("implementation_acceptance") == "complete" for row in products),
        "reference_gaps": {
            "declared_source_maps_missing": sum(row.get("acquisition", {}).get("reference_gaps", {}).get("declared_source_maps_missing", 0) for row in products),
            "unattributed_source_maps_missing": sum(row.get("acquisition", {}).get("reference_gaps", {}).get("unattributed_source_maps_missing", 0) for row in products),
            "declared_non_map_missing": sum(len(row.get("acquisition", {}).get("reference_gaps", {}).get("declared_non_map_missing", [])) for row in products),
            "undeclared_probes_unavailable": sum(len(row.get("acquisition", {}).get("reference_gaps", {}).get("undeclared_probes_unavailable", [])) for row in products),
            "unattributed_non_map_missing": sum(len(row.get("acquisition", {}).get("reference_gaps", {}).get("unattributed_non_map_missing", [])) for row in products),
            "original_opaque_factories_verified": sum(row.get("analysis", {}).get("opaque_factory_originals", {}).get("verified_factories", 0) for row in products)},
    }
    a.save(path, {key: value for key, value in matrix.items() if not key.startswith("_")})


def paired_deployments(pid, family="mouse"):
    layers = {}
    for layer, namespace in (("ui", family), ("mw", family + "-mw")):
        folder = a.ROOT / f".analysis/inputs/frontend/{namespace}-{pid}-current"
        endpoint = f"https://apps.razer.com/synapse/products/{pid}/{layer}/manifest.json"
        found = None
        for name in ("acquisition.json", "probe.json"):
            receipt = folder / name
            if not receipt.is_file():
                continue
            data = json.loads(receipt.read_bytes())
            source = next((item for item in data.get("files", []) if item.get("url") == endpoint and "path" in item), None)
            if source and valid(source):
                manifest = json.loads((a.ROOT / source["path"]).read_bytes())
                found = {"source": {key: source[key] for key in ("path", "bytes", "sha256")},
                         "receipt": identity(receipt), "version": manifest.get("version"),
                         "build_version": manifest.get("buildVersion"), "git_metadata": manifest.get("gitMetadata"),
                         "deployment_stable": data.get("source_current_during_acquisition", False)}
                break
        layers[layer] = found
    return {"pairing": "same official product ID; independent UI and middleware deployment metadata",
            "layers": layers, "api_compatibility_semantic_audit": "pending"}


def acquire_family_native(matrix, acquire=True):
    """Merge all retained endpoint scopes, preserving other product acquisitions."""
    receipt = a.ROOT / ".analysis/inputs/official-native-current/acquisition.json"
    previous = json.loads(receipt.read_bytes()) if receipt.is_file() else {}
    endpoints = {item["url"] for item in previous.get("manifests", [])}
    if acquire:
        for row in matrix["products"]:
            pid = row["product_id"]
            endpoint = f"https://apps.razer.com/synapse/products/{pid}/mw/manifest.json"
            probe = a.ROOT / row["input"] / "probe.json"
            data = json.loads(probe.read_bytes())
            source = next((item for item in data["files"] if item["url"] == endpoint and "path" in item), None)
            if source is None or not valid(source):
                raise ValueError(f"Product {pid} lacks verified official middleware manifest provenance")
            endpoints.add(endpoint)
        a.acquire_native(SimpleNamespace(manifest_url=sorted(endpoints), no_refresh_gaps=True))
    result = json.loads(receipt.read_bytes())
    manifests = {item["url"]: item for item in result.get("manifests", [])}
    stability = {item["url"]: item for item in result.get("stability", [])}
    for row in matrix["products"]:
        endpoint = f'https://apps.razer.com/synapse/products/{row["product_id"]}/mw/manifest.json'
        manifest = manifests.get(endpoint, {})
        resources = [item for item in result.get("resources", [])
                     if any(parent["url"] == endpoint for parent in item.get("manifests", []))]
        verified = [item for item in resources if item.get("status") == "verified" and valid(item)]
        declared = manifest.get("resources", [])
        missing_resources = [item for item in declared if not any(
            candidate.get("url") == item.get("url")
            and candidate.get("sha256", "").lower() == item.get("sha256", "").lower()
            and candidate.get("bytes") == item.get("size") for candidate in verified)]
        observed_stability = stability.get(endpoint)
        unverified = []
        if not result.get("finished_at_utc"):
            unverified.append("Native acquisition completion receipt is absent")
        if not manifest or not valid(manifest):
            unverified.append("Native manifest original bytes are unverified")
        if observed_stability is None or observed_stability.get("unchanged") is not True:
            unverified.append("Native manifest deployment stability is unverified")
        if missing_resources:
            unverified.append("Some declared native resources lack verified original bytes")
        row["native_resources"] = {
            "receipt": identity(receipt), "manifest": manifest,
            "completed": not unverified, "unverified_reasons": unverified,
            "deployment_stability": observed_stability,
            "declared_resources": len(declared), "missing_resources": missing_resources,
            "verified_resources": len(verified),
            "resources": resources, "native_code_semantic_audit": "pending",
            "installer_execution": False, "real_device_operations": False}


def acquisition_details(receipt):
    data = json.loads(receipt.read_bytes())
    originals = [row for row in data["files"] if "path" in row]
    identities_verified = bool(originals) and all(valid(row) for row in originals)
    # A finished crawl may have changed deployments, missing resources or stale
    # local bytes. Keep that outcome separate from a complete acquisition.
    complete = (identities_verified and data.get("source_current_during_acquisition", False)
                and data.get("declared_references_fetched", False) and not data.get("unresolved"))
    return {"completed": complete, "run_finished": "source_current_during_acquisition" in data,
            "identities_verified": identities_verified, "receipt": a.rel(receipt),
            "unresolved_references": len(data.get("unresolved", [])),
            "files": len(data["files"]), "retained_files": sum("path" in item for item in data["files"]),
            "unavailable_files": sum("path" not in item for item in data["files"]),
            "bytes": sum(item.get("bytes", 0) for item in data["files"]),
            "deployment_stable": data.get("source_current_during_acquisition", False),
            "declared_references_fetched": data.get("declared_references_fetched", False),
            "reference_gaps": frontend_reference_gaps(data)}


def frontend_reference_gaps(data):
    """Keep unavailable debug maps, exploratory probes and declared assets separate."""
    declared = {}
    for edge in data.get("edges", []):
        target = edge.get("to", edge.get("url"))
        if (not isinstance(target, str) or not target
                or "to" in edge and "url" in edge and edge["to"] != edge["url"]):
            raise ValueError("Frontend reference edge has no unique target URL")
        declared.setdefault(target, []).append(edge)
    probes = {row["url"] for row in data.get("probes", []) if row.get("declared") is False}
    counts = Counter()
    missing, speculative, unknown = [], [], []
    for row in data["files"]:
        if "path" in row:
            continue
        url = row["url"]
        is_map = urllib.parse.urlsplit(url).path.endswith(".map")
        if url in declared and is_map:
            counts["declared_source_maps"] += 1
        elif url in declared:
            missing.append({**row, "declared_by": declared[url]})
        elif url in probes:
            speculative.append(row)
        elif is_map:
            counts["unattributed_source_maps"] += 1
        else:
            unknown.append(row)
    return {"declared_source_maps_missing": counts["declared_source_maps"],
            "unattributed_source_maps_missing": counts["unattributed_source_maps"],
            "declared_non_map_missing": missing, "undeclared_probes_unavailable": speculative,
            "unattributed_non_map_missing": unknown,
            "all_declared_non_map_references_retained": not missing,
            "unresolved_by_kind": dict(Counter(item["kind"] for item in data.get("unresolved", []))),
            "unresolved_chunk_selectors": [item for item in data.get("unresolved", []) if item["kind"] == "chunk_unresolved"]}


def extract_native_packages(args, ids):
    workers = getattr(args, "workers", 2)
    if type(workers) is not int or not 2 <= workers <= 16:
        raise ValueError("Native package workers must be between two and sixteen")
    acquisition_path = a.ROOT / ".analysis/inputs/official-native-current/acquisition.json"
    acquisition = json.loads(acquisition_path.read_bytes())
    endpoints = set(getattr(args, "manifest_url", None) or
                    [f"https://apps.razer.com/synapse/products/{pid}/mw/manifest.json" for pid in ids])
    resources = [item for item in acquisition["resources"] if item.get("status") == "verified"
                 and any(parent["url"] in endpoints for parent in item["manifests"])]
    if getattr(args, "include_manifest_mismatches", False):
        for item in acquisition["resources"]:
            observed = item.get("observed_artifact")
            if (item.get("status") != "verified" and observed
                    and any(parent["url"] in endpoints for parent in item["manifests"])):
                resources.append({**observed, "manifests": item["manifests"],
                                  "status": "manifest_mismatch_investigation",
                                  "declared_sha256": item["declared_sha256"],
                                  "declared_bytes": item["declared_bytes"],
                                  "manifest_acquisition_error": item["error"]})
    # Follow only indexed extraction/container relationships rooted in this
    # family's actual manifest resources. Nested payloads never acquire a new
    # declaration or erase the original manifest mismatch.
    inherited = {item["path"]: item for item in resources}
    indexed = json.loads((a.ROOT / ".analysis/inputs.json").read_bytes())["inputs"]
    retained_extractions = {}
    extraction_prefix = ".analysis/inputs/official-native-current/extracted/"
    for artifact in indexed:
        if artifact["path"].startswith(extraction_prefix):
            digest = artifact["path"][len(extraction_prefix):].split("/", 1)[0]
            retained_extractions.setdefault(digest, {})[artifact["path"]] = artifact
    children = {}
    for item in indexed:
        if (not item.get("container") or item.get("container_extraction_complete") is False
                or item.get("source_bytes_verified") is False):
            continue
        aliases = {item["container"]: item["container_sha256"]}
        for alias in item.get("container_aliases", []):
            if alias.get("byte_identity_verified") is not True:
                continue
            if alias["sha256"] != item["container_sha256"]:
                raise ValueError("Nested container alias identifies different parent bytes")
            aliases[alias["path"]] = alias["sha256"]
        for path, digest in aliases.items():
            children.setdefault(path, []).append((item, digest))
    pending = deque(resources)
    visited = set()
    while pending:
        parent = pending.popleft()
        for item, digest in children.get(parent["path"], []):
            if digest != parent["sha256"]:
                raise ValueError("Nested indexed input has a different container identity")
            root = parent.get("root_resource", parent["path"])
            edge = (item["path"], parent["path"], root, parent["url"], parent["status"])
            if edge in visited:
                continue
            visited.add(edge)
            child = {**parent, **item, "container": parent["path"], "container_sha256": digest,
                     "url": parent["url"], "status": parent["status"],
                     "declared_sha256": parent["declared_sha256"], "declared_bytes": parent["declared_bytes"],
                     "verified_against_manifest": parent["status"] == "verified",
                     "manifests": parent["manifests"], "root_resource": root}
            inherited[item["path"]] = child
            resources.append(child)
            pending.append(child)
    tool = Path(args.seven_zip)
    if not tool.is_file():
        raise ValueError("Static 7-Zip extractor is unavailable")
    tool_identity = {"executable": identity(tool) if tool.is_relative_to(a.ROOT) else
                     {"name": tool.name, "sha256": a.sha(tool)},
                     "library_sha256": a.sha(tool.with_name("7z.dll"))}
    result_path = a.ROOT / f".analysis/results/families/{args.family}-native.json"
    previous_failures = []
    if result_path.is_file():
        previous = json.loads(result_path.read_bytes())
        previous_failures.extend(previous.get("previous_failures", []))
        previous_identity = identity(result_path)
        for package in previous.get("packages", []):
            if (package.get("error") or package.get("extraction_exit_code", 0) != 0
                    or package.get("inno_setup", {}).get("archive_entry_closure", {}).get("complete") is False):
                previous_failures.append({"previous_result": previous_identity, "package": package})
    result = {"schema_version": 1, "acquisition": identity(acquisition_path), "tool": tool_identity,
              "products": ids, "packages": [], "target_execution": False,
              "previous_failures": previous_failures,
              "includes_manifest_mismatch_investigation": bool(getattr(args, "include_manifest_mismatches", False)),
              "installer_branch_semantic_audit": "pending"}
    by_sha = {}
    resource_bindings = {}
    archive_extensions = {".exe", ".zip", ".cab", ".msi", ".7z", ".msix"}

    def add_resource(item):
        if item.get("container_extraction_complete") is False or item.get("source_bytes_verified") is False:
            return
        if Path(item["path"]).suffix.lower() not in archive_extensions:
            # Burn/MSI payloads frequently have opaque names such as a0/u4.
            # Classify original bytes before excluding them from recursion.
            source = a.resolve(item["path"], ".analysis/inputs")
            with source.open("rb") as stream:
                prefix = stream.read(8)
            if not prefix.startswith((b"MZ", b"PK\x03\x04", b"PK\x05\x06", b"MSCF",
                                      b"7z\xbc\xaf\x27\x1c", b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1")):
                return
        inherited[item["path"]] = item
        binding = {key: item[key] for key in ("url", "status", "declared_sha256", "declared_bytes", "manifests")}
        for key in ("root_resource", "container", "container_sha256", "container_offset"):
            if key in item:
                binding[key] = item[key]
        binding["verified_against_manifest"] = item["status"] == "verified"
        if "manifest_acquisition_error" in item:
            binding["manifest_acquisition_error"] = item["manifest_acquisition_error"]
        bindings = resource_bindings.setdefault(item["sha256"], [])
        if binding not in bindings:
            bindings.append(binding)
        if item["sha256"] not in by_sha or (item["status"] == "verified"
                and by_sha[item["sha256"]]["status"] != "verified"):
            by_sha[item["sha256"]] = item

    for item in resources:
        add_resource(item)

    def extract(item):
        if not valid(item):
            raise ValueError("Native container differs from its retained acquisition bytes")
        bindings = resource_bindings[item["sha256"]]
        binding = next(row for row in bindings if row["url"] == item["url"] and row["status"] == item["status"])
        source = a.ROOT / item["path"]
        output = a.ROOT / ".analysis/results/native-packages" / item["sha256"]
        destination = a.ROOT / ".analysis/inputs/official-native-current/extracted" / item["sha256"]
        receipt = output / "inspection.json"
        if receipt.is_file():
            retained = json.loads(receipt.read_bytes())
            listing_path = (output / "restoration/listing.stdout.txt" if retained.get("restoration")
                            else output / "listing.stdout.txt")
            unresolved_listing = listing_path.is_file() and b"BadCmd=" in listing_path.read_bytes()
            empty_archive = (retained.get("extracted") is False and not retained.get("files")
                             and retained.get("entry_count") == 0 and retained.get("extraction_exit_code") == 0)
            if ((unresolved_listing or empty_archive) and retained.get("tool") != tool_identity
                    and retained.get("outputs") and all(valid(row) for row in retained["outputs"])):
                import host
                restored = host.restore_static_archive(
                    {key: item[key] for key in ("path", "bytes", "sha256")}, tool.resolve(), destination,
                    retained_extractions.get(item["sha256"], {}), retained, output / "restoration",
                    "static_extracted_native_input")
                files = [{**artifact, "container_extraction_complete": True,
                          "verified_against_manifest": binding["verified_against_manifest"],
                          "declared_container_sha256": item["declared_sha256"]} for artifact in restored["files"]]
                replacement = {**retained, "tool": tool_identity, "files": files,
                               "recorded_at_utc": a.stamp(), "extracted": bool(files),
                               "extraction_exit_code": restored["extraction_exit_code"],
                               "entry_count": len(restored["archive_entries"]),
                               "restoration": identity(output / "restoration/capture.json"),
                               "outputs": restored["outputs"], "current_resource_binding": binding,
                               "current_resource_bindings": bindings}
                if not files:
                    replacement["limitation"] = "Static archive has zero payload entries; installer code semantics remain pending"
                a.save(receipt, replacement)
                return replacement
            if (empty_archive and retained.get("tool") == tool_identity and not unresolved_listing
                    and destination.is_dir() and not any(destination.iterdir())
                    and valid(retained["container"]) and retained.get("outputs")
                    and all(valid(row) for row in retained["outputs"])):
                return {**retained, "current_resource_binding": binding, "current_resource_bindings": bindings,
                        "inspection_reused": True,
                        "limitation": "Static archive has zero payload entries; installer code semantics remain pending"}
            if retained.get("extracted") and all(valid(row) for row in retained["files"] + retained.get("reconstructed_outputs", [])):
                actual = {a.rel(path) for path in destination.rglob("*") if path.is_file()}
                if actual == {row["path"] for row in retained["files"]}:
                    return {**retained, "current_resource_binding": binding,
                            "current_resource_bindings": bindings}
            if (retained.get("extracted") is False and not retained.get("files")
                    and not destination.exists()
                    and retained.get("listing_exit_code") == 0 and retained.get("tool") == tool_identity
                    and retained.get("limitation") == "No supported embedded archive detected; PE section listing does not establish payload closure"
                    and retained.get("container", {}).get("sha256") == item["sha256"]
                    and valid(retained["container"]) and retained.get("outputs")
                    and all(valid(row) for row in retained["outputs"])):
                return {**retained, "current_resource_binding": binding,
                        "current_resource_bindings": bindings, "inspection_reused": True}
            if retained.get("files") or destination.exists():
                raise ValueError("Existing native extraction requires inspection before replacement")
        output.mkdir(parents=True, exist_ok=True)
        listing = subprocess.run([str(tool), "l", "-slt", str(source)], capture_output=True, check=False)
        (output / "listing.stdout.txt").write_bytes(listing.stdout)
        (output / "listing.stderr.txt").write_bytes(listing.stderr)
        listing_text = listing.stdout.decode("utf-8", errors="replace")
        formats = re.findall(r"^Type = (.+)$", listing_text.replace("\r", ""), re.M)
        format_args = []
        supported_formats = {"Nsis", "7z", "zip", "Cab", "Compound"}
        inno = None
        inno_metadata = None
        if (not set(formats) & supported_formats and source.read_bytes()[:2] == b"MZ"
                and b"PK\x03\x04" in source.read_bytes()):
            forced = subprocess.run([str(tool), "l", "-tzip", "-slt", str(source)], capture_output=True, check=False)
            (output / "listing-forced-zip.stdout.txt").write_bytes(forced.stdout)
            (output / "listing-forced-zip.stderr.txt").write_bytes(forced.stderr)
            forced_text = forced.stdout.decode("utf-8", errors="replace")
            forced_formats = re.findall(r"^Type = (.+)$", forced_text.replace("\r", ""), re.M)
            if forced.returncode == 0 and "zip" in forced_formats:
                listing, listing_text, formats, format_args = forced, forced_text, forced_formats, ["-tzip"]
        if not set(formats) & supported_formats:
            marker = re.search(rb"Inno Setup Setup Data \(([^)\0]+)\)", source.read_bytes())
            if marker:
                import host
                inno, inno_receipt = host.prepare_inno_analyzer()
                inno_listing = subprocess.run([str(inno), "-s", "-h", "-o", "-u", "-b", "-m", "-a", str(source)],
                                             capture_output=True, check=False)
                (output / "inno-listing.stdout.txt").write_bytes(inno_listing.stdout)
                (output / "inno-listing.stderr.txt").write_bytes(inno_listing.stderr)
                inno_metadata = {"declared_setup_data_version": marker[1].decode("ascii"),
                    "list_exit_code": inno_listing.returncode,
                    "analyzer": {"name": inno_receipt["name"], "version": inno_receipt["version"],
                                 "path": a.rel(inno), "sha256": a.sha(inno),
                                 "acquisition": identity(inno.parent / "acquisition.json")}}
                if inno_listing.returncode == 0:
                    entries = host.inno_archive_entries(inno_listing.stdout)
                    formats.append("Inno Setup")
                    inno_metadata["archive_entries"] = entries
        record = {"container": {key: item[key] for key in ("path", "bytes", "sha256")},
                  "recorded_at_utc": a.stamp(), "tool": tool_identity, "formats": formats,
                  "listing_exit_code": listing.returncode, "files": [], "extracted": False,
                  "current_resource_binding": binding,
                  "current_resource_bindings": bindings,
                  "format_arguments": format_args,
                  "target_execution": False, "installer_branch_semantic_audit": "pending"}
        if inno_metadata:
            record["inno_setup"] = inno_metadata
        if (inno_metadata and "Inno Setup" in formats) or (listing.returncode == 0 and set(formats) & supported_formats):
            if not inno:
                payload = listing_text.replace("\r", "").split("----------\n", 1)
                if len(payload) != 2:
                    raise ValueError("Cannot locate complete static archive entry listing")
                entries = re.findall(r"^Path = (.+)$", payload[1], re.M)
            for entry in entries:
                path = PureWindowsPath(entry)
                if path.is_absolute() or path.drive or ".." in path.parts or any(":" in part for part in path.parts):
                    raise ValueError("Unsafe static archive entry path")
            if not inno and re.search(r"^(?:Symbolic Link|Hard Link) =", payload[1], re.M):
                raise ValueError("Archive links require a separate static extraction audit")
            record["entry_count"] = len(entries)
            record["duplicate_entry_paths"] = {name: count for name, count in Counter(entries).items() if count > 1}
            if destination.exists():
                raise ValueError("Unrecorded extraction destination already exists")
            destination.mkdir(parents=True, exist_ok=False)
            command = ([str(inno), "-x", "-b", "-q", "-m", "-a", "-o", "-u", "-d" + str(destination), str(source)]
                       if inno else [str(tool), "x", *format_args, "-y", "-aou", "-bb3", str(source), "-o" + str(destination)])
            process = subprocess.run(command, capture_output=True, check=False)
            (output / "extraction.stdout.txt").write_bytes(process.stdout)
            (output / "extraction.stderr.txt").write_bytes(process.stderr)
            record["extraction_exit_code"] = process.returncode
            record["duplicate_handling"] = "7-Zip -aou preserves colliding entry variants; branch-to-variant mapping remains pending"
            if inno:
                record["duplicate_handling"] = "Inno static extractor -m/-a preserves installer entry variants; branch-to-variant mapping remains pending"
                generated = destination / "install_script.iss"
                script = output / "install_script.iss"
                if generated.is_file():
                    if script.exists() and script.read_bytes() != generated.read_bytes():
                        raise ValueError("Reconstructed Inno script changed during static extraction")
                    generated.replace(script)
                record["reconstructed_outputs"] = ([{**identity(script), "kind": "analyzer_reconstructed_installer_script",
                                                      "is_original_input": False}] if script.is_file() else [])
            for path in sorted(destination.rglob("*")):
                if (path.is_symlink() or path.is_junction()
                        or not a._resolved_path_identity(path.resolve()).is_relative_to(
                            a._resolved_path_identity(destination.resolve()))):
                    raise ValueError("Extracted path escaped private source directory")
                if path.is_file():
                    record["files"].append({**identity(path), "kind": "static_extracted_native_input",
                                            "container": item["path"], "container_sha256": item["sha256"],
                                            "verified_against_manifest": binding["verified_against_manifest"],
                                            "declared_container_sha256": item["declared_sha256"]})
            record["input_bytes_unchanged"] = valid(item)
            if inno:
                expected = {entry.replace("\\", "/") for entry in entries}
                actual = {Path(artifact["path"]).relative_to(destination.relative_to(a.ROOT)).as_posix() for artifact in record["files"]}
                if record["reconstructed_outputs"]:
                    actual.add("install_script.iss")
                record["inno_setup"]["archive_entry_closure"] = {"missing": sorted(expected - actual),
                    "unexpected": sorted(actual - expected), "complete": expected == actual}
            record["extracted"] = (process.returncode == 0 and bool(record["files"]) and record["input_bytes_unchanged"]
                                   and (not inno or record["inno_setup"]["archive_entry_closure"]["complete"]))
            for artifact in record["files"]:
                artifact["container_extraction_complete"] = record["extracted"]
                if not record["extracted"]:
                    artifact["source_bytes_verified"] = False
                    artifact["source_validation_failure"] = "Static decompression failed; retained partial bytes are not original-source evidence"
        else:
            record["limitation"] = "No supported embedded archive detected; PE section listing does not establish payload closure"
        record["outputs"] = [identity(path) for path in sorted(output.iterdir()) if path.is_file() and path.name != "inspection.json"]
        a.save(receipt, record)
        return record

    processed = set()
    while set(by_sha) - processed:
        current = [item for sha, item in by_sha.items() if sha not in processed]
        processed.update(item["sha256"] for item in current)
        index_updates = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(workers, 2)) as pool:
            pending = {pool.submit(extract, item): item for item in current}
            for future in concurrent.futures.as_completed(pending):
                item = pending[future]
                try:
                    row = future.result()
                except Exception as error:
                    bindings = resource_bindings[item["sha256"]]
                    row = {"container": {key: item[key] for key in ("path", "bytes", "sha256")},
                           "current_resource_binding": next(binding for binding in bindings
                               if binding["url"] == item["url"] and binding["status"] == item["status"]),
                           "current_resource_bindings": bindings, "error": str(error), "extracted": False}
                for child in row.get("files", []):
                    add_resource({**item, **child, "url": item["url"], "status": item["status"],
                                  "declared_sha256": item["declared_sha256"], "declared_bytes": item["declared_bytes"],
                                  "manifests": item["manifests"], "root_resource": item.get("root_resource", item["path"])})
                index_updates.extend(row.get("files", []))
                result["packages"].append(row)
                # Successful per-container receipts are already durable and
                # reusable. Avoid rewriting the full multi-megabyte aggregate
                # for every cached package; preserve fresh failures immediately.
                if row.get("error") or len(result["packages"]) % 25 == 0:
                    a.save(result_path, result)
                print(json.dumps({"container": item["sha256"], "extracted": row["extracted"], "files": len(row.get("files", [])), "error": row.get("error")}), flush=True)
        if index_updates:
            # Each package receipt is already durable. Publish one merge per
            # recursion wave; a resumed wave also republishes verified cached
            # outputs if a previous process stopped before this index merge.
            a.index_files(index_updates)
        a.save(result_path, result)
    result["summary"] = {"packages": len(result["packages"]), "extracted": sum(row["extracted"] for row in result["packages"]),
                         "files": sum(len(row.get("files", [])) for row in result["packages"]),
                         "manifest_mismatch_packages": sum(any(binding["verified_against_manifest"] is False
                             for binding in row.get("current_resource_bindings", [])) for row in result["packages"])}
    a.save(result_path, result)
    print(json.dumps({"result": a.rel(result_path), **result["summary"]}), flush=True)


def probe_product(row):
    pid = row["product_id"]
    output = a.ROOT / row["input"]
    bundle_manifest = "webpackManifest.json" if row.get("layer") == "mw" else "asset-manifest.json"
    urls = [row["entry_url"], urllib.parse.urljoin(row["entry_url"], bundle_manifest),
            f"https://apps.razer.com/synapse/products/{pid}/mw/manifest.json"]
    files = [a.download(url, output) for url in urls]
    receipt = output / "probe.json"
    manifest = None
    if "path" in files[1]:
        try:
            manifest = json.loads((a.ROOT / files[1]["path"]).read_bytes())
        except (ValueError, OSError) as error:
            files[1]["parse_error"] = str(error)
    middleware = None
    if "path" in files[2]:
        try:
            middleware = json.loads((a.ROOT / files[2]["path"]).read_bytes())
        except (ValueError, OSError) as error:
            files[2]["parse_error"] = str(error)
    data = {"schema_version": 1, "product_id": pid, "recorded_at_utc": a.stamp(), "files": files,
            "target_execution": False, "real_device_operations": False}
    a.save(receipt, data)
    return {"receipt": a.rel(receipt), "entry_available": "path" in files[0],
            "manifest_available": "path" in files[1],
            "manifest_declared_files": len(manifest.get("files", manifest if row.get("layer") == "mw" else {})) if isinstance(manifest, dict) else None,
            "manifest_entrypoints": manifest.get("entrypoints", []) if isinstance(manifest, dict) else [],
            "middleware_version": middleware.get("version") if isinstance(middleware, dict) else None,
            "middleware_build_version": middleware.get("buildVersion") if isinstance(middleware, dict) else None,
            "middleware_git_metadata": middleware.get("gitMetadata") if isinstance(middleware, dict) else None,
            "failures": [r for r in files if "error" in r or "parse_error" in r]}


def retained_probe_details(row):
    """Rebuild locator metadata from actual current receipts without HTTP work.

    Acquisition supersedes the initial probe for mutable entry/manifest URLs.
    A removed matrix field is not evidence that retained original inputs vanished.
    Failed byte identities remain failures, never cached availability claims.
    """
    folder = a.ROOT / row["input"]
    receipts = []
    for filename in ("acquisition.json", "probe.json"):
        receipt = folder / filename
        if receipt.is_file():
            receipts.append((receipt, json.loads(receipt.read_bytes())))
    if not receipts:
        return None
    pid = row["product_id"]
    bundle = "webpackManifest.json" if row.get("layer") == "mw" else "asset-manifest.json"
    urls = (row["entry_url"], urllib.parse.urljoin(row["entry_url"], bundle),
            f"https://apps.razer.com/synapse/products/{pid}/mw/manifest.json")
    originals, failures = [], []
    for url in urls:
        found = None
        for receipt, data in receipts:
            candidate = next((item for item in data.get("files", []) if item.get("url") == url), None)
            if candidate is not None:
                found = {**candidate, "receipt": a.rel(receipt)}
                break
        if found is None:
            failures.append({"url": url, "error": "Locator endpoint absent from retained receipts"})
        elif not valid(found):
            failures.append({**found, "identity_error": "Retained locator bytes unavailable or changed"})
        originals.append(found if found is not None and valid(found) else None)
    parsed = []
    for original in originals[1:]:
        try:
            parsed.append(json.loads((a.ROOT / original["path"]).read_bytes()) if original else None)
        except (ValueError, OSError) as error:
            failures.append({"input": original, "parse_error": str(error)})
            parsed.append(None)
    manifest, middleware = parsed
    return {"receipt": a.rel(receipts[0][0]), "input_receipts": [a.rel(path) for path, _ in receipts],
            "entry_available": originals[0] is not None, "manifest_available": originals[1] is not None,
            "manifest_declared_files": len(manifest.get("files", manifest if row.get("layer") == "mw" else {}))
                if isinstance(manifest, dict) else None,
            "manifest_entrypoints": manifest.get("entrypoints", []) if isinstance(manifest, dict) else [],
            "middleware_version": middleware.get("version") if isinstance(middleware, dict) else None,
            "middleware_build_version": middleware.get("buildVersion") if isinstance(middleware, dict) else None,
            "middleware_git_metadata": middleware.get("gitMetadata") if isinstance(middleware, dict) else None,
            "originals": originals, "failures": failures,
            "method": "Retained acquisition first, probe second; actual byte identity verified"}


class SharedArtifacts:
    """Reuse verified bytes only for the identical official URL, never a short name/hash."""
    def __init__(self):
        self.rows = {}
        self.by_sha = {}
        self.fresh_urls = set()
        self.lock = threading.Lock()
        for receipt in (a.ROOT / ".analysis/inputs/frontend").glob("*/acquisition.json"):
            for row in json.loads(receipt.read_bytes()).get("files", []):
                if "path" in row:
                    self.rows.setdefault(row["url"], row)
        self.verified = set()

    def download(self, url, output):
        try:
            return self._download(url, output)
        except (OSError, ValueError) as error:
            # Cache reuse is optional. Keep its diagnostic and use the normal
            # acquisition path, which records an individual artifact failure.
            row = a.download(url, output)
            row["cache_reuse_failure"] = {"error": str(error), "output": a.rel(output)}
            print(json.dumps({"cache_reuse_failure": row["cache_reuse_failure"], "url": url}), flush=True)
            return row

    def _download(self, url, output):
        row = self.rows.get(url)
        immutable = re.search(r"\.[0-9a-f]{8,64}(?:\.chunk)?\.", urllib.parse.urlsplit(url).path)
        if row is not None and (immutable or url in self.fresh_urls):
            if row["path"] not in self.verified and valid(row):
                self.verified.add(row["path"])
            if row["path"] in self.verified:
                destination = a.raw_path(output, url)
                destination.parent.mkdir(parents=True, exist_ok=True)
                source = a.ROOT / row["path"]
                if not destination.exists():
                    shutil.copyfile(source, destination)
                if a.sha(destination) != row["sha256"]:
                    return {"url": url, "error": "Shared artifact destination differs", "acquired_at_utc": a.stamp()}
                return {**row, "path": a.rel(destination), "reused_from": row["path"], "reused_at_utc": a.stamp()}
        return self._remember(a.download(url, output))

    def reacquire(self, url, output):
        # A damaged original must be fetched from its official URL, not trusted
        # because an earlier cache lookup marked the same path as verified.
        with self.lock:
            previous = self.rows.pop(url, None)
            if previous:
                self.verified.discard(previous["path"])
            self.fresh_urls.discard(url)
        # download() deliberately refuses to overwrite different retained
        # bytes. Fetch into a private staging directory and verify that fresh
        # receipt before atomically replacing only this URL's damaged original.
        scratch = a.ROOT / ".work"
        scratch.mkdir(parents=True, exist_ok=True)
        try:
            with tempfile.TemporaryDirectory(prefix="family-repair-", dir=scratch) as staging:
                acquired = a.download(url, Path(staging))
                if "path" in acquired:
                    if not valid(acquired):
                        raise ValueError("Reacquired original does not match its HTTP receipt")
                    destination = a.raw_path(output, url)
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    (a.ROOT / acquired["path"]).replace(destination)
                    acquired["path"] = a.rel(destination)
                    with self.lock:
                        self.by_sha = {digest: path for digest, path in self.by_sha.items()
                                       if path != acquired["path"]}
                return self._remember(acquired)
        except (OSError, ValueError) as error:
            return {"url": url, "error": str(error), "acquired_at_utc": a.stamp()}

    def _remember(self, acquired):
        if "path" in acquired:
            with self.lock:
                # Different official URLs each retain their own HTTP receipt;
                # record duplicate bodies after hashing, but keep originals
                # independent of concurrent refreshes to another product.
                original = self.by_sha.get(acquired["sha256"])
                if original is not None and original != acquired["path"]:
                    acquired["identical_bytes_also_at"] = original
                self.by_sha.setdefault(acquired["sha256"], acquired["path"])
                self.rows[acquired["url"]] = acquired
                self.verified.add(acquired["path"])
                self.fresh_urls.add(acquired["url"])
        return acquired


def acquire_product(row, shared, retry_transient=False, index_artifacts=None, retry_declared_missing=False):
    index_artifacts = index_artifacts or a.index_files
    print(json.dumps({"acquiring": row["input"], "repair": retry_transient}), flush=True)
    output = a.ROOT / row["input"]
    receipt = output / "acquisition.json"
    probe = output / "probe.json"
    try:
        if not receipt.is_file() and probe.is_file():
            files = json.loads(probe.read_bytes())["files"][:3 if row.get("layer") == "mw" else 2]
            a.save(receipt, {"schema_version": 1, "entry_url": row["entry_url"], "files": files})
        if retry_transient and receipt.is_file():
            previous = json.loads(receipt.read_bytes())
            # A valid old manifest is still an old deployment. Refresh the
            # explicit failed stability endpoints, otherwise every repair keeps
            # crawling the retained old hashes and fails the same final audit.
            stale_urls = {item["url"] for item in previous.get("stability", [])
                          if not item.get("unchanged")}
            declared_urls = {previous["entry_url"], *(edge["to"] for edge in previous.get("edges", []))}
            for index, item in enumerate(previous["files"]):
                damaged = "path" in item and not valid(item)
                stale_deployment = item["url"] in stale_urls
                declared_missing = (retry_declared_missing and "error" in item and item["url"] in declared_urls
                                    and not urllib.parse.urlsplit(item["url"]).path.endswith(".map"))
                if damaged or stale_deployment or declared_missing or ("error" in item and "HTTP Error 404" not in item["error"]):
                    unverified_retained = "path" not in item and a.raw_path(output, item["url"]).is_file()
                    replacement = (shared.reacquire if damaged or stale_deployment or unverified_retained
                                   else shared.download)(item["url"], output)
                    replacement["previous_attempts"] = item.get("previous_attempts", []) + [
                        {key: value for key, value in item.items() if key != "previous_attempts"}]
                    if damaged:
                        replacement["repair_reason"] = "Original bytes missing or different from acquisition identity"
                    elif stale_deployment:
                        replacement["repair_reason"] = "Deployment identity changed or stability recheck failed"
                    elif unverified_retained:
                        replacement["repair_reason"] = "Retained URL bytes have no verified acquisition identity"
                    elif declared_missing:
                        replacement["repair_reason"] = "Explicit retry of a source-declared non-map missing resource"
                    previous["files"][index] = replacement
            # Old stability describes the old acquisition. A failed resumed
            # crawl must not inherit its completion claim.
            previous.pop("source_current_during_acquisition", None)
            previous.pop("declared_references_fetched", None)
            a.save(receipt, previous)
        seed_urls = []
        if row.get("layer") == "mw":
            # Repair may legitimately fetch a newer official manifest. Its
            # fresh acquisition receipt supersedes the older probe identity.
            source_rows = json.loads(receipt.read_bytes())["files"] if receipt.is_file() else []
            if probe.is_file():
                source_rows += json.loads(probe.read_bytes())["files"]
            for name in ("webpackManifest.json", "manifest.json"):
                endpoint = urllib.parse.urljoin(row["entry_url"], name)
                source = next((item for item in source_rows if item["url"] == endpoint
                               and "path" in item and valid(item)), None)
                if source is None:
                    raise ValueError("Middleware manifest seed lacks verified official probe bytes: " + endpoint)
                seed_urls.append(endpoint)
        a.fetch_frontend(SimpleNamespace(url=row["entry_url"], output=row["input"], download_artifact=shared.download,
                                        seed_urls=seed_urls, index_artifacts=index_artifacts), refresh_ledger=False)
        return acquisition_details(receipt)
    except Exception as error:
        if receipt.is_file():
            index_artifacts(rows_for_index(json.loads(receipt.read_bytes()).get("files", []), receipt))
        return {"completed": False, "error": str(error), "receipt": a.rel(receipt)}


def translation_routes(originals):
    """Inventory literal lazy-context routes without evaluating vendor JavaScript."""
    routes = []
    embedded_maps = []
    inline_dictionaries = []
    pattern = re.compile(r'"(?P<route>\./(?P<context>[^"/]+)/translations/(?P<language>[a-z]{2}(?:-[A-Za-z]{2})?))"\s*:\s*(?P<modules>\[\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\])')
    for source in originals:
        if Path(urllib.parse.urlsplit(source["url"]).path).suffix != ".js":
            continue
        body = (a.ROOT / source["path"]).read_text(encoding="utf-8")
        language_pattern = r'(de|en|es|fr|ja|kr|pt-BR|ru|zh-CN|zh-TW)'
        inline_patterns = [r'(?:\{|,)' + language_pattern + r':\{\s*[A-Z][A-Z_0-9]+:',
                           r',"' + language_pattern + r'",\{\s*[A-Z][A-Z_0-9]+:']
        declarations = [{"language": match[1], "character_offset": match.start()}
                        for pattern in inline_patterns for match in re.finditer(pattern, body)]
        if declarations:
            inline_dictionaries.append({"source": {key: source[key] for key in ("path", "bytes", "sha256")},
                                        "declarations": declarations,
                                        "languages": sorted({item["language"] for item in declarations})})
        for match in re.finditer(r'\{de:[^{}]{0,400}?en:[^{}]{0,400}?kr:[^{}]{0,400}?ru:[^{}]{0,400}?\}', body):
            declaration = match.group()
            direct = re.findall(r'(?:\{|,)([a-z]{2}):', declaration)
            computed = re.findall(r'\[([A-Za-z_$][\w$]*)\]:', declaration)
            constants = dict(re.findall(r'([A-Za-z_$][\w$]*)="([a-z]{2}-[A-Za-z]{2})"', body[max(0, match.start()-1000):match.start()]))
            embedded_maps.append({"source": {key: source[key] for key in ("path", "bytes", "sha256")},
                                  "character_offset": match.start(), "declaration": declaration,
                                  "languages": sorted(set(direct + [constants[name] for name in computed if name in constants])),
                                  "unresolved_computed_keys": [name for name in computed if name not in constants]})
        for match in pattern.finditer(body):
            modules = json.loads(match["modules"])
            prefix = str(modules[2]) + "."
            artifacts = [{key: item[key] for key in ("path", "bytes", "sha256")}
                         for item in originals if Path(item["path"]).name.startswith(prefix)
                         and item["path"].endswith(".chunk.js")]
            routes.append({"route": match["route"], "context": match["context"],
                           "language": match["language"], "webpack_module": modules[0], "webpack_chunk": modules[2],
                           "source": {key: source[key] for key in ("path", "bytes", "sha256")},
                           "character_offset": match.start(), "chunk_artifacts": artifacts})
    return {"method": "literal webpack translation context map; static extraction only",
            "routes": routes, "languages": sorted({item["language"] for item in routes}),
            "embedded_dictionary_maps": embedded_maps,
            "inline_dictionary_declarations": inline_dictionaries,
            "contexts": sorted({item["context"] for item in routes}),
            "all_route_chunks_retained": all(item["chunk_artifacts"] for item in routes) if routes else None,
            "full_dictionary_semantic_audit": "pending"}


def analyze_product(row, recover=True, refresh_ledger=True):
    input_dir = a.ROOT / row["input"]
    acquisition = json.loads((input_dir / "acquisition.json").read_bytes())
    originals = [item for item in acquisition["files"] if "path" in item]
    if not originals or not all(valid(item) for item in originals):
        raise ValueError("Current original input byte verification failed")
    snapshot = [{key: item[key] for key in ("path", "bytes", "sha256")} for item in originals]
    receipt = a.ROOT / ".analysis/results/frontend" / input_dir.name / "analysis.json"
    previous = json.loads(receipt.read_bytes()) if receipt.is_file() else {}
    reusable = (previous.get("original_inputs") == snapshot and previous.get("outputs")
                and all(valid(item) for item in previous["outputs"]))
    if not reusable:
        if not recover:
            return {"completed": False, "run_finished": False,
                    "receipt": a.rel(receipt), "current_inputs_verified": False,
                    "error": "No recovery receipt matching the current original and output bytes"}
        a.analyze_frontend(SimpleNamespace(input=row["input"], refresh=receipt.is_file()),
                           refresh_ledger=refresh_ledger)
    result = json.loads(receipt.read_bytes())
    outputs_valid = bool(result["outputs"]) and all(valid(item) for item in result["outputs"])
    inputs_valid = result.get("original_inputs") == snapshot and all(valid(item) for item in originals)
    findings = Counter()
    finding_origins = Counter()
    original_paths = {item["path"] for item in originals}
    for command in result["commands"]:
        if command["stage"] == "validate":
            try:
                validation = json.loads((a.ROOT / command["stdout"]).read_bytes())
                findings.update(item["kind"] for item in validation.get("findings", []))
                source_cache = {}
                for item in validation.get("findings", []):
                    filename = item.get("filename", "")
                    if filename not in source_cache:
                        mapping_path = receipt.parent / "modules" / (filename + ".map")
                        sources = []
                        if mapping_path.is_file():
                            for source in json.loads(mapping_path.read_bytes()).get("sources", []):
                                path = (mapping_path.parent / source).resolve()
                                if path.is_relative_to(a.ROOT):
                                    relative = a.rel(path)
                                    if relative in original_paths:
                                        sources.append(relative)
                        source_cache[filename] = tuple(sources)
                    finding_origins[(item["kind"], source_cache[filename])] += 1
            except (OSError, ValueError, KeyError):
                findings["validation_report_unavailable"] += 1
    failed = [{"stage": command["stage"], "exit_code": command["exit_code"]}
              for command in result["commands"] if command["exit_code"]]
    supplements = supplement_opaque_factories(result, receipt) if outputs_valid and inputs_valid else None
    return {"completed": outputs_valid and inputs_valid and result.get("input_bytes_unchanged", False) and not failed,
            "run_finished": True, "receipt": a.rel(receipt), "original_js_inputs": len(result["original_js_inputs"]),
            "outputs": len(result["outputs"]), "outputs_verified": outputs_valid,
            "current_inputs_verified": inputs_valid, "failed_stages": failed,
            "validation_findings": dict(findings), "translations": translation_routes(originals),
            "validation_origins": [{"kind": kind, "original_inputs": list(sources), "findings": count}
                                   for (kind, sources), count in sorted(finding_origins.items())],
            "opaque_factory_originals": supplements or {"verified_factories": 0}, "semantic_audit": "pending"}


def supplement_opaque_factories(captured, receipt):
    """Retain complete original ASTs when safe factory normalization fails."""
    import importlib.metadata
    outputs = {row["path"]: row for row in captured["outputs"]}
    warnings = []
    for command in captured["commands"]:
        if command["stage"] != "unpack":
            continue
        stdout = outputs.get(command["stdout"])
        if stdout is None or not valid(stdout):
            raise ValueError("Factory recovery diagnostics do not verify")
        warnings.extend(row for row in json.loads((a.ROOT / stdout["path"]).read_bytes()).get("warnings", [])
                        if row.get("is_error") and row.get("kind") == "webpack_factory_recovery_failed")
    if not warnings:
        return None
    provenance_row = next((row for row in outputs.values() if row["path"].endswith("/modules/provenance.json")), None)
    if provenance_row is None or not valid(provenance_row):
        raise ValueError("Opaque factory provenance does not verify")
    provenance = json.loads((a.ROOT / provenance_row["path"]).read_bytes())
    raw_root = (a.ROOT / captured["input"] / "raw").resolve()
    originals = {row["path"]: row for row in captured["original_inputs"]}
    factories, source_cache = [], {}
    for warning in warnings:
        name = warning["filename"]
        match = re.fullmatch(r"module-(\d+)\.js", name)
        owner = provenance["modules"].get(name)
        if match is None or owner is None or owner.get("extraction") != "structural":
            raise ValueError("Opaque factory has no numeric structural owner")
        source_path = (raw_root / owner["input"].replace("\\", "/")).resolve()
        if not source_path.is_relative_to(raw_root):
            raise ValueError("Opaque factory original escapes its input root")
        source = originals.get(a.rel(source_path))
        if source is None or not valid(source):
            raise ValueError("Opaque factory original input bytes differ")
        if source["path"] not in source_cache:
            text = source_path.read_text(encoding="utf-8")
            source_cache[source["path"]] = (text, keyboard_source_modules(text))
        text, modules = source_cache[source["path"]]
        selected = [module for module in modules if module["module_id"] == int(match[1])]
        if len(selected) != 1:
            raise ValueError("Opaque factory original module is absent or ambiguous")
        factory = webpack_factory_snapshot(selected[0])
        if owner["ranges"] != [[factory["statements_byte_start"], factory["statements_byte_end"]]]:
            raise ValueError("Opaque factory complete statement boundaries differ from analyzer provenance")
        output = outputs.get(a.rel(receipt.parent / "modules" / name))
        if output is None or not valid(output):
            raise ValueError("Opaque transformed module bytes differ")
        factories.append({"original": source, "warning": warning, "analyzer_provenance": owner,
                          "opaque_transformed_output": output, **factory})
    supplement = {"tool": identity(Path(__file__)), "recovery_analyzer": captured["tool"],
                  "parsers": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
                  "provenance": provenance_row, "factories": factories,
                  "complete_original_factory_bytes_verified": True,
                  "safe_factory_transformation": "unresolved; original analyzer failures retained",
                  "target_execution": False, "semantic_audit": "pending", "runtime_acceptance": "unverified"}
    captured["opaque_factory_supplement"] = supplement
    a.save(receipt, captured)
    return {"receipt": identity(receipt), "verified_factories": len(factories),
            "original_inputs": sorted(source_cache), "safe_factory_transformation": "unresolved"}


def run(args, shared=None, refresh=True):
    run_error = None
    try:
        return _run(args, shared)
    except BaseException as error:
        run_error = error
        raise
    finally:
        # Persisted success and failure rows must precede the final derived
        # ledger. A multi-family batch refreshes once after all children finish.
        if refresh:
            try:
                a.refresh_gaps()
            except Exception as error:
                print(json.dumps({"gap_refresh": {"completed": False, "error": str(error),
                                  "family_rows": "retained; analysis results are unchanged"}}), flush=True)
                if run_error is None:
                    raise RuntimeError(f"Family rows retained; final gaps refresh failed: {error}") from error


def refresh_family_scope_index():
    """Keep locator counts tied to the complete current UI/MW matrices."""
    ids = set()
    endpoint_probes = 0
    receipts = []
    reference_counts, unresolved_counts = Counter(), Counter()
    declared_missing = []
    for family in FAMILY_CANDIDATES:
        expected, _ = family_candidate_scope(family)
        ids.update(expected)
        for layer in ("ui", "mw"):
            namespace = family if layer == "ui" else family + "-mw"
            path = a.ROOT / ".analysis/results/families" / (namespace + ".json")
            matrix = json.loads(path.read_bytes())
            actual = {row["product_id"] for row in matrix["products"]}
            if (matrix.get("family") != family or matrix.get("layer") != layer
                    or actual != set(expected)):
                raise ValueError("Family matrix does not match the full current locator scope: " + a.rel(path))
            endpoint_probes += matrix["summary"]["probed"]
            receipts.append(identity(path))
            reference_counts.update(matrix["summary"].get("reference_gaps", {}))
            for product in matrix["products"]:
                gaps = product.get("acquisition", {}).get("reference_gaps", {})
                unresolved_counts.update(gaps.get("unresolved_by_kind", {}))
                declared_missing.extend({"family": family, "layer": layer, "product_id": product["product_id"], **row}
                                        for row in gaps.get("declared_non_map_missing", []))
    with a.index_lock():
        path = a.ROOT / ".analysis/inputs.json"
        index = json.loads(path.read_bytes())
        source = index.setdefault("current_sources", {}).setdefault("devices", {})
        source.update(candidate_products=len(ids), ui_mw_endpoint_probes=endpoint_probes,
                      family_matrices=".analysis/results/families",
                      locator_scope={"recorded_at_utc": a.stamp(), "product_ids": sorted(ids),
                                     "matrix_receipts": receipts,
                                      "usage": "Endpoint discovery only; does not prove current source closure or implementation acceptance"},
                      reference_closure={"counts": dict(reference_counts), "unresolved_by_kind": dict(unresolved_counts),
                                         "declared_non_map_missing": declared_missing,
                                         "usage": "Verified retained acquisition and analyzer receipts; missing maps, exploratory probes, declared files and unresolved loaders are separate"})
        a.save(path, index)
    return {"candidate_products": len(ids), "ui_mw_endpoint_probes": endpoint_probes, "reference_closure": dict(reference_counts)}


def _run(args, shared=None):
    if args.family == "all" or args.layer == "both":
        if args.family == "all" and (args.candidates or args.product):
            raise ValueError("Explicit candidates/product IDs require a single family")
        families = list(FAMILY_CANDIDATES) if args.family == "all" else [args.family]
        layers = ["ui", "mw"] if args.layer == "both" else [args.layer]
        if args.stage in {"native", "extract-native"}:
            # Native acquisition merges one common manifest receipt.
            for family in families:
                run(SimpleNamespace(**(vars(args) | {"family": family, "layer": "mw"})), refresh=False)
            return
        shared = SharedArtifacts()
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(args.workers, 6)) as pool:
            jobs = {pool.submit(run, SimpleNamespace(**(vars(args) | {"family": family, "layer": layer})), shared, False):
                    (family, layer) for family in families for layer in layers}
            failures = []
            for future in concurrent.futures.as_completed(jobs):
                family, layer = jobs[future]
                try:
                    future.result()
                except Exception as error:
                    failures.append({"family": family, "layer": layer, "error": str(error)})
        if failures:
            raise ValueError(json.dumps({"family_failures": failures}))
        if args.family == "all" and args.layer == "both":
            print(json.dumps({"family_scope": refresh_family_scope_index()}), flush=True)
        return
    candidate_path = (a.ROOT / args.candidates if args.candidates else
        a.builtin_data_path("razer-pages", FAMILY_CANDIDATES[args.family]))
    ids = candidates(candidate_path)
    scope = None
    if not args.candidates:
        ids, scope = family_candidate_scope(args.family)
    family_ids = list(ids)
    if args.product:
        unknown = set(args.product) - set(ids)
        if unknown:
            raise ValueError(f"Product IDs absent from family candidates: {sorted(unknown)}")
        ids = sorted(set(args.product))
    if args.stage == "extract-native":
        return extract_native_packages(args, ids)
    namespace = args.family if args.layer == "ui" else args.family + "-" + args.layer
    matrix_path = a.ROOT / ".analysis/results/families" / (namespace + ".json")
    old = json.loads(matrix_path.read_bytes()) if matrix_path.is_file() else {}
    old_rows = {row["product_id"]: row for row in old.get("products", [])}
    matrix = {"schema_version": 1, "family": args.family, "layer": args.layer, "candidate_locator": identity(candidate_path),
              "candidate_usage": "product_id discovery only; names/pages/legacy source references are not implementation evidence",
              "route_evidence": route_evidence(), "tool": identity(Path(__file__)),
              "target_execution": False, "real_device_operations": False,
              "_baseline_rows": deepcopy(old_rows), "product_scope": scope,
              "products": [{"semantic_audit": "pending", "implementation_acceptance": "pending",
                            **old_rows.get(pid, {}), "product_id": pid, "layer": args.layer,
                            "entry_url": f"https://apps.razer.com/synapse/products/{pid}/{args.layer}/index.html",
                            "input": f".analysis/inputs/frontend/{namespace}-{pid}-current"} for pid in sorted(set(family_ids) | old_rows.keys())]}
    selected = [row for row in matrix["products"] if row["product_id"] in ids]
    save_matrix(matrix_path, matrix)
    print(json.dumps({"family": args.family, "products": len(ids), "stage": args.stage}), flush=True)
    probes = selected if args.stage in {"probe", "all"} else []
    if args.stage in {"acquire", "repair"}:
        probes = [row for row in selected if not (a.ROOT / row["input"] / "probe.json").is_file()
                  and not (a.ROOT / row["input"] / "acquisition.json").is_file()]
    if probes:
        indexed = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
            futures = {pool.submit(probe_product, row): row for row in probes}
            for future in concurrent.futures.as_completed(futures):
                row = futures[future]
                try:
                    row["probe"] = future.result()
                    receipt = a.ROOT / row["probe"]["receipt"]
                    indexed.extend(rows_for_index(json.loads(receipt.read_bytes())["files"], receipt))
                except Exception as error:
                    row["probe"] = {"entry_available": False, "error": str(error)}
                save_matrix(matrix_path, matrix)
                print(json.dumps({"product_id": row["product_id"], "probe": row["probe"]}), flush=True)
        # One atomic merge per family/layer. Rewriting the complete input index
        # per product starves other families and misreports lock contention as
        # an unavailable official endpoint.
        if indexed:
            a.index_files(indexed)
    shared = shared or SharedArtifacts()
    if args.stage in {"acquire", "repair", "all"}:
        pending = selected
        if args.stage == "repair":
            pending = []
            for row in selected:
                receipt = a.ROOT / row["input"] / "acquisition.json"
                result = json.loads(receipt.read_bytes()) if receipt.is_file() else {}
                damaged = any("path" in item and not valid(item) for item in result.get("files", []))
                if damaged:
                    row["analysis"] = {"completed": False, "run_finished": False,
                                       "current_inputs_verified": False,
                                       "error": "Original bytes require repair; reverify static recovery against repaired inputs"}
                    row["semantic_audit"] = "pending"
                    row["implementation_acceptance"] = "pending"
                if (result.get("reference_parser_version") != a.FRONTEND_REFERENCE_VERSION
                    or not result.get("source_current_during_acquisition")
                    or damaged
                    or (getattr(args, "retry_declared_missing", False) and any(
                        "error" in item and not urllib.parse.urlsplit(item["url"]).path.endswith(".map")
                        and item["url"] in {result.get("entry_url"), *(edge["to"] for edge in result.get("edges", []))}
                        for item in result.get("files", [])))
                    or any("error" in item and "HTTP Error 404" not in item["error"] for item in result.get("files", []))):
                    pending.append(row)
        print(json.dumps({"family": args.family, "layer": args.layer,
                          "pending_acquisitions": len(pending)}), flush=True)
        indexed = []
        index_mutex = threading.Lock()
        def collect_index(rows):
            with index_mutex:
                indexed.extend(rows)
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(args.workers, 3)) as pool:
            futures = {pool.submit(bounded_call, ACQUISITION_SLOTS, acquire_product,
                                   row, shared, args.stage == "repair", collect_index,
                                   getattr(args, "retry_declared_missing", False)): row for row in pending}
            for future in concurrent.futures.as_completed(futures):
                row = futures[future]
                try:
                    row["acquisition"] = future.result()
                except Exception as error:
                    row["acquisition"] = {"completed": False, "error": str(error)}
                save_matrix(matrix_path, matrix)
                row["paired_deployments"] = paired_deployments(row["product_id"], args.family)
                save_matrix(matrix_path, matrix)
                print(json.dumps({"product_id": row["product_id"], "acquisition": row["acquisition"]}), flush=True)
        # Resume also republishes receipts from an interrupted prior batch,
        # including stable products which correctly need no new HTTP crawl.
        # Artifact rows retain their acquisition's expected byte identities;
        # no observed mismatch is promoted by this index merge.
        for row in selected:
            receipt = a.ROOT / row["input"] / "acquisition.json"
            if receipt.is_file():
                collect_index(rows_for_index(json.loads(receipt.read_bytes()).get("files", []), receipt))
        if indexed:
            a.index_files(indexed)
    if args.stage == "native":
        acquire_family_native({**matrix, "products": selected})
        save_matrix(matrix_path, matrix)
    if args.stage == "report":
        for row in selected:
            probe = retained_probe_details(row)
            if probe is not None:
                row["probe"] = probe
            receipt = a.ROOT / row["input"] / "acquisition.json"
            if receipt.is_file():
                row["acquisition"] = acquisition_details(receipt)
                analysis = a.ROOT / ".analysis/results/frontend" / receipt.parent.name / "analysis.json"
                if analysis.is_file():
                    try:
                        row["analysis"] = analyze_product(row, recover=False)
                    except (OSError, ValueError, KeyError) as error:
                        row["analysis"] = {"completed": False, "run_finished": False, "error": str(error)}
                else:
                    row["analysis"] = {"completed": False, "run_finished": False,
                                       "error": "Static recovery receipt is absent"}
            else:
                row["acquisition"] = {"completed": False, "run_finished": False,
                                      "identities_verified": False, "error": "Acquisition receipt is absent"}
                row["analysis"] = {"completed": False, "run_finished": False,
                                   "error": "Original acquisition receipt is absent"}
            if not row["acquisition"].get("identities_verified"):
                row["semantic_audit"] = "pending"
                row["implementation_acceptance"] = "pending"
            row["paired_deployments"] = paired_deployments(row["product_id"], args.family)
        native_receipt = a.ROOT / ".analysis/inputs/official-native-current/acquisition.json"
        if native_receipt.is_file():
            acquire_family_native({**matrix, "products": selected}, acquire=False)
        save_matrix(matrix_path, matrix)
    if args.stage in {"analyze", "all"}:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(args.workers, 2)) as pool:
            futures = {pool.submit(bounded_call, ANALYSIS_SLOTS, analyze_product, row, True, False): row for row in selected}
            for future in concurrent.futures.as_completed(futures):
                row = futures[future]
                try:
                    row["analysis"] = future.result()
                except Exception as error:
                    row["analysis"] = {"completed": False, "run_finished": False, "error": str(error)}
                save_matrix(matrix_path, matrix)
                print(json.dumps({"product_id": row["product_id"],
                                  "analysis": {key: value for key, value in row["analysis"].items() if key != "translations"}}), flush=True)
    print(json.dumps({"family_matrix": a.rel(matrix_path), **matrix["summary"]}), flush=True)


def audit_middleware_capture(family, pid):
    """Verify the current MW deployment and its reusable complete capture."""
    import host
    audit = host.HostLocalAudit()
    name = f"{family}-mw-{pid}-current"
    source_set, originals = audit.source_set(name)
    deployment = source_set["deployment"]
    if deployment["failures"]:
        raise ValueError("Current middleware deployment differs: " + json.dumps(deployment["failures"]))
    mounted = [row for row in deployment["sources"] if row["deployment_role"] == "html_include"
               and row["original"] is not None and Path(row["original"]["path"]).name.startswith("main.")
               and row["original"]["path"].endswith(".js")]
    if len(mounted) != 1:
        raise ValueError("Current middleware mounted main is absent or ambiguous")
    capture = audit.frontend_capture(name, originals)
    if audit.final_snapshot():
        raise ValueError("Current middleware original/capture bytes changed during verification")
    return {"source_set": source_set, "mounted_main": mounted[0]["original"],
            "original_inputs": originals, "complete_capture": capture,
            "failures": ["complete_capture_stage_failed"] if capture["capture_failures"] else []}


