def matcher_numeric_ast(audit, owner, *, matcher):
    """Verify one complete original factory and retain only small AST identities."""
    import frontend
    original = owner["original"]
    raw = audit.read(original)
    start, end = owner["byte_start"], owner["byte_end"]
    if type(start) is not int or type(end) is not int or not 0 <= start < end <= len(raw):
        raise ValueError("Matcher numeric factory range exceeds its original")
    node = audit.tree(original).root_node.descendant_for_byte_range(start, end - 1)
    while node is not None and (node.start_byte != start or node.end_byte != end):
        node = node.parent
    if (node is None or node.type not in {"pair", "method_definition"}
            or node.type != owner["syntax"]
            or hashlib.sha256(raw[start:end]).hexdigest() != owner["body_sha256"]
            or frontend.syntax_identity(node) != owner["syntax_sha256"]):
        raise ValueError("Matcher numeric factory is not its complete original AST owner")
    key = node.child_by_field_name("key") or node.child_by_field_name("name")
    if key is None or javascript_integer_literal(key.text.decode()) != owner["module_id"]:
        raise ValueError("Matcher numeric factory module identity changed")
    requirements = {
        "dynamic_raw_tick": ("variable_declarator", "l=e.timeTick"),
        "dynamic_comparison": ("binary_expression", "0!==M.lastTimeTick&&l>M.lastTimeTick"),
        "dynamic_duration": ("augmented_assignment_expression", "r+=l-M.lastTimeTick"),
        "dynamic_tick_update": ("assignment_expression", "M.lastTimeTick=l"),
        "dynamic_speed_gate": ("binary_expression", "r>0&&(M.speed=Math.sqrt(Math.pow(o,2)+Math.pow(i,2))/(r/1e4))"),
        "dynamic_nan_consumer": ("assignment_expression", "M.speed=Math.abs(isNaN(M.speed)?0:M.speed)")}
    if matcher:
        requirements.update({
            "matcher_unary_tick": ("unary_expression", "+e.timeTick"),
            "matcher_progress": ("assignment_expression", "M.process=Math.min(Math.round(M.main.traveledDistance/M.main.maxTravelDistance*100),99)"),
            "matcher_distance_filter": ("binary_expression", "n.x<=0||n.timeTick<t"),
            "matcher_stop_gate": ("binary_expression", "M.main.maxTravelDistance<=M.main.traveledDistance&&M.stoptime<=M.source.events[M.source.events.length-1].timeTick"),
            "matcher_result": ("assignment_expression", "M.newDpi=Math.round(a/r*M.main.currentDpi)"),
            "matcher_local_baseline": ("return_statement", "return(null===(e=o.dpiStages)||void 0===e?void 0:e.stages[(null===(t=o.dpiStages)||void 0===t?void 0:t.active)-1].x)||100")})
    hits = {role: [] for role in requirements}
    pending = [node]
    while pending:
        child = pending.pop()
        for role, (syntax, expression) in requirements.items():
            if child.type == syntax and child.text.decode() == expression:
                hits[role].append(child)
        pending.extend(reversed(child.named_children))
    if any(len(rows) != 1 for rows in hits.values()):
        raise ValueError("Matcher numeric consumer AST is absent or ambiguous")
    callback = hits["dynamic_raw_tick"][0]
    while callback is not None and callback.type != "arrow_function":
        callback = callback.parent
    if callback is None:
        raise ValueError("Matcher dynamic Tick callback has no complete AST owner")
    callback_nodes, pending = [], [callback]
    while pending:
        child = pending.pop()
        if child.type == "if_statement":
            callback_nodes.append(child.text.decode())
        pending.extend(reversed(child.named_children))
    if callback_nodes != ['if("mouseMove"!==t.type||!n)return;']:
        raise ValueError("Matcher dynamic Tick callback has an additional event guard")
    hits["dynamic_event_callback"] = [callback]
    return {role: {"byte_start": rows[0].start_byte, "byte_end": rows[0].end_byte,
        "syntax": rows[0].type, "body_sha256": hashlib.sha256(rows[0].text).hexdigest(),
        "syntax_sha256": frontend.syntax_identity(rows[0])} for role, rows in hits.items()}


def validate_mouse_matcher_numeric_scope(review):
    if (review.get("kind") != MATCHER_NUMERIC_KIND or review.get("schema_version") != 1
            or review.get("target_execution") is not False or review.get("whole_page_complete") is not False
            or review.get("source_semantics_complete") is not False
            or review.get("actual_dll_comparison") != "unverified" or review.get("runtime_acceptance") != "unverified"
            or review.get("rust_validation") != "not_executed_by_this_static_review"
            or review.get("source_review") != MATCHER_NUMERIC_REVALIDATION
            or review.get("semantics") != matcher_numeric_semantics()
            or review.get("remaining_local_chains") != MATCHER_NUMERIC_REMAINING
            or review.get("scratch_resources_created") != [] or "complete_owners" in review):
        raise ValueError("Matcher numeric review has a different scope or verification boundary")
    rows = review.get("products", [])
    if [row.get("product_id") for row in rows] != list(MATCHER_NUMERIC_PRODUCTS) + [196]:
        raise ValueError("Matcher numeric review must cover six Matcher and seven dynamic branches exactly")
    if [row.get("path") for row in review.get("rust_inputs", [])] != list(MATCHER_NUMERIC_RUST_INPUTS):
        raise ValueError("Matcher numeric review has incomplete Rust input ownership")
    return rows


def verify_mouse_matcher_numeric_review(review):
    """Resolve frozen references against indexed official bytes, never copied JS."""
    import host
    rows = validate_mouse_matcher_numeric_scope(review)
    audit = host.HostLocalAudit()
    index = json.loads((a.ROOT / ".analysis/inputs.json").read_bytes())["inputs"]
    indexed = {}
    for item in index:
        indexed.setdefault(item["path"], []).append(item)
    checked_index = {}

    def indexed_original(original):
        matches = indexed.get(original["path"], [])
        if len(matches) != 1 or any(matches[0].get(key) != original[key] for key in ("bytes", "sha256")):
            raise ValueError("Matcher numeric original/acquisition differs from its input index")
        checked_index[original["path"]] = {key: original[key] for key in ("path", "bytes", "sha256")}

    source = json.loads(audit.artifact(a.ROOT / review["source_review"]["path"], review["source_review"]))
    if source.get("kind") != "mouse_matcher_deployment_owner_comparison" or source.get("target_execution") is not False:
        raise ValueError("Matcher numeric source reference has a different deployment scope")
    sources = {row["product_id"]: row for row in source["source_sets"] if row["layer"] == "mw"}
    for row in rows:
        pid = row["product_id"]
        if row.get("matcher") is not (pid != 196):
            raise ValueError("Matcher numeric product has a conflicting capability scope")
        if pid != 196:
            comparisons = [item for item in source["owner_comparisons"]
                if item["product_id"] == pid and item["roles"] == ["monitor_factory"]]
            if (len(comparisons) != 1 or row.get("factory_reference") != {
                    "review_source": review["source_review"], "owner": comparisons[0]["new_owner"]}
                    or row.get("acquisition") != sources[pid]["acquisition"]):
                raise ValueError("Matcher numeric product references a different complete factory")
            owner = source["complete_factories"][comparisons[0]["new_owner"]]
        else:
            owner = row.get("factory", {})
            if (owner.get("original", {}).get("sha256") != "df8334aa3021d129893918cecb3c1d14b3727f476c42981bac3fb02f6736b633"
                    or (owner.get("byte_start"), owner.get("byte_end"), owner.get("module_id")) != (1137610, 1146581, 32807)
                    or owner.get("body_sha256") != "02be331a6c05b2689f411ab125ca774d96636db41e2ff4646d69f19d9b414afb"
                    or "body" in owner or "factory_reference" in row):
                raise ValueError("Matcher dynamic196 reference is not the retained original complete factory")
        original = owner["original"]
        if not re.search(r"/products/" + str(pid) + r"/mw/[^/]+\.js$", original["path"]):
            raise ValueError("Matcher numeric original belongs to a different product")
        indexed_original(original)
        indexed_original(row["acquisition"])
        acquired = json.loads(audit.artifact(a.ROOT / row["acquisition"]["path"], row["acquisition"]))
        acquired_matches = [item for item in acquired.get("files", []) if item.get("path") == original["path"]]
        if (acquired.get("source_current_during_acquisition") is not True
                or acquired.get("target_execution") is not False
                or acquired.get("entry_url") != f"https://apps.razer.com/synapse/products/{pid}/mw/index.html"
                or len(acquired_matches) != 1
                or any(acquired_matches[0].get(key) != original[key] for key in ("bytes", "sha256"))):
            raise ValueError("Matcher numeric acquisition does not own its actual official original")
        if row.get("consumers") != matcher_numeric_ast(audit, owner, matcher=pid != 196):
            raise ValueError("Matcher numeric consumer reference differs from its complete original AST")
    for item in review["rust_inputs"]:
        path = a.resolve(item["path"], "crates")
        if identity(path) != item:
            raise ValueError("Matcher numeric Rust input identity changed")
    if audit.final_snapshot() or any(not valid(item) for item in review["rust_inputs"]):
        raise ValueError("Matcher numeric source bytes changed during verification")
    return {"artifacts": [*audit.artifacts.values(), *review["rust_inputs"]],
            "indexed_originals": list(checked_index.values())}


def collect_mouse_matcher_numeric_review():
    """Reuse the immutable six-factory comparison and the retained dynamic196 owner."""
    import frontend
    import host
    audit = host.HostLocalAudit()
    source = json.loads(audit.artifact(a.ROOT / MATCHER_NUMERIC_REVALIDATION["path"], MATCHER_NUMERIC_REVALIDATION))
    products = []
    for pid in MATCHER_NUMERIC_PRODUCTS:
        comparison, = [item for item in source["owner_comparisons"]
            if item["product_id"] == pid and item["roles"] == ["monitor_factory"]]
        owner = source["complete_factories"][comparison["new_owner"]]
        source_set, = [item for item in source["source_sets"] if item["product_id"] == pid and item["layer"] == "mw"]
        products.append({"product_id": pid, "matcher": True, "acquisition": source_set["acquisition"],
            "factory_reference": {"review_source": deepcopy(MATCHER_NUMERIC_REVALIDATION), "owner": comparison["new_owner"]},
            "consumers": matcher_numeric_ast(audit, owner, matcher=True)})
    section = json.loads((a.ROOT / ".analysis/results/frontend/mouse-mw-audit.json").read_bytes())["queries"]["dynamic_sensitivity"]
    product, = [item for item in section["products"] if item["product_id"] == 196]
    retained = section["complete_owners"][product["monitor_factory"]]
    owner = {key: retained[key] for key in ("original", "byte_start", "byte_end", "syntax", "body_sha256")}
    node = audit.tree(owner["original"]).root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
    owner.update({"module_id": 32807, "syntax_sha256": frontend.syntax_identity(node)})
    products.append({"product_id": 196, "matcher": False, "factory": owner,
        "acquisition": identity(a.ROOT / ".analysis/inputs/frontend/mouse-mw-196-current/acquisition.json"),
        "consumers": matcher_numeric_ast(audit, owner, matcher=False)})
    review = {"schema_version": 1, "kind": MATCHER_NUMERIC_KIND, "source_review": deepcopy(MATCHER_NUMERIC_REVALIDATION),
        "products": products, "semantics": matcher_numeric_semantics(),
        "rust_inputs": [identity(a.ROOT / name) for name in MATCHER_NUMERIC_RUST_INPUTS],
        "remaining_local_chains": list(MATCHER_NUMERIC_REMAINING), "scratch_resources_created": [],
        "target_execution": False, "whole_page_complete": False, "source_semantics_complete": False,
        "rust_validation": "not_executed_by_this_static_review", "actual_dll_comparison": "unverified",
        "runtime_acceptance": "unverified"}
    verify_mouse_matcher_numeric_review(review)
    return review


def retained_mouse_matcher_numeric_review(document):
    references = [document["queries"][name].get("numeric_boundary_review") for name in ("dpi_matcher", "dynamic_sensitivity")]
    if references[0] != references[1]:
        raise ValueError("Matcher numeric query references conflict")
    reference = references[0]
    if reference is None:
        return None, None
    if (not isinstance(reference, dict) or set(reference) != {"path", "bytes", "sha256"}
            or not isinstance(reference.get("sha256"), str) or not re.fullmatch(r"[a-f0-9]{64}", reference["sha256"])
            or reference.get("path") != ".analysis/results/reverse-pending/review-sources/" + reference["sha256"] + ".json"
            or type(reference.get("bytes")) is not int or reference["bytes"] <= 0 or not valid(reference)):
        raise ValueError("Retained Matcher numeric review has an invalid immutable identity")
    review = json.loads((a.ROOT / reference["path"]).read_bytes())
    if (review.get("kind") != MATCHER_NUMERIC_KIND or review.get("target_execution") is not False
            or review.get("whole_page_complete") is not False):
        raise ValueError("Retained Matcher numeric review has a different scope")
    return deepcopy(reference), review


def audit_mouse_matcher_numeric_boundary(args):
    """Freeze or check one bounded review through the shared semantic publisher."""
    import os
    if (args.family != "mouse" or args.function != "mw" or args.query != "mouse-dpi-matcher"
            or getattr(args, "prepare", False) or getattr(args, "receipt_only", False)
            or args.product is not None and sorted(set(args.product)) != sorted((*MATCHER_NUMERIC_PRODUCTS, 196))):
        raise ValueError("Matcher numeric boundary requires all six Matcher and seven dynamic mouse mw branches")
    canonical = a.ROOT / ".analysis/results/frontend/mouse-mw-audit.json"
    with a.index_lock():
        previous, retained = retained_mouse_matcher_numeric_review(json.loads(canonical.read_bytes()))
    if args.matcher_numeric_boundary == "check":
        if retained is None:
            raise ValueError("Matcher numeric boundary has no published retained review")
        verify_mouse_matcher_numeric_review(retained)
        result = {"review_source": previous, "products": list(MATCHER_NUMERIC_PRODUCTS) + [196],
            "target_execution": False, "whole_page_complete": False, "runtime_acceptance": "unverified"}
        print(json.dumps(result), flush=True)
        return result
    review = collect_mouse_matcher_numeric_review()
    publication = copy.copy(args)
    if retained is not None and {key: value for key, value in retained.items() if key != "previous_review_source"} == review:
        publication.semantic_review, publication.semantic_review_sha256 = previous["path"], previous["sha256"]
    else:
        if previous is not None:
            review["previous_review_source"] = previous
        raw = (json.dumps(review, ensure_ascii=False, indent=2) + "\n").replace("\n", os.linesep).encode("utf-8")
        digest = hashlib.sha256(raw).hexdigest()
        path = a.ROOT / ".analysis/results/reverse-pending/review-sources" / (digest + ".json")
        if path.exists():
            if path.read_bytes() != raw:
                raise ValueError("Matcher numeric hash-addressed review collides with retained bytes")
        else:
            a.save(path, review)
            if path.read_bytes() != raw:
                raise ValueError("Matcher numeric frozen serialization differs from the shared publisher")
        publication.semantic_review, publication.semantic_review_sha256 = a.rel(path), digest
    publication.semantic_previous_review = previous
    return publish_frontend_semantic_review(publication)


def merge_frontend_semantic_review(document, review, reference, *, expected_previous_review=None):
    """Add one reviewed semantic slice without replacing sibling audit state."""
    import copy
    if review["kind"] == MATCHER_NUMERIC_KIND:
        validate_mouse_matcher_numeric_scope(review)
        references = [document["queries"][name].get("numeric_boundary_review") for name in ("dpi_matcher", "dynamic_sensitivity")]
        current = references[0]
        if (references[0] != references[1] or current != reference and
                (current != expected_previous_review or review.get("previous_review_source") != current)):
            raise ValueError("Matcher numeric review conflicts with a newer or removed retained review")
        for name in ("dpi_matcher", "dynamic_sensitivity"):
            document["queries"][name]["numeric_boundary_review"] = deepcopy(reference)
        return {"products": list(MATCHER_NUMERIC_PRODUCTS) + [196], "complete_factory_references": 7,
            "fields": ["queries/dpi_matcher/numeric_boundary_review", "queries/dynamic_sensitivity/numeric_boundary_review"],
            "whole_page_complete": False}
    incoming = review["complete_owners"]

    def same_owner(left, right):
        return (all(left[key] == right[key] for key in ("byte_start", "byte_end", "body_sha256", "body"))
            and all(left["original"][key] == right["original"][key] for key in ("path", "bytes", "sha256")))

    if review["kind"] == "current_keyboard_wireless_power_review":
        rows = validate_keyboard_power_review(review)
        queries = document.setdefault("queries", {})
        current = queries.get("keyboard-wireless-power")
        if (current is not None and current.get("review_source") != reference
                and current.get("review_source") != expected_previous_review):
            raise ValueError("Keyboard Power review conflicts with a newer retained review")
        queries["keyboard-wireless-power"] = {
            "review_source": reference, "products": deepcopy(review["products"]),
            "source_sets": deepcopy(review["source_sets"]), "semantics": deepcopy(review["semantics"]),
            **({"host_ble_transport": deepcopy(review["host_ble_transport"])} if "host_ble_transport" in review else {}),
            "remaining_local_chains": deepcopy(review["remaining_local_chains"]),
            "target_execution": False, "whole_page_complete": False,
            "rust_implementation": "unverified", "ui_backend_wiring": "unverified",
            "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified"}
        return {"products": sorted(rows), "complete_owners": len(review["complete_owners"]),
                "field": "queries/keyboard-wireless-power", "whole_page_complete": False}
    if review["kind"] == "current_legacy_receiver_mapping_descriptor_review":
        section = document["receiver_legacy"]
        products = {row["product_id"]: row for row in section["products"]}
        reviewed = {row["product_id"]: row for row in review["products"]}
        if (set(reviewed) != set(LEGACY_RECEIVER_MAPPING_PRODUCTS) or len(reviewed) != len(review["products"])
                or set(products) != set(reviewed) or review["base_selection_review"] != section["runtime_selection_review"]
                or review["host_descriptor_review"] != MAPPING_DESCRIPTOR_HOST_REVIEW
                or review["target_execution"] or review["whole_page_complete"]
                or review["actual_dll_comparison"] != "unverified" or review["independent_execution_connected"]):
            raise ValueError("Receiver mapping descriptor join has a different scope, source or verification boundary")
        current = section.get("mapping_descriptor_contract")
        if (current is not None and current.get("review_source") != reference
                and current.get("review_source") != expected_previous_review):
            raise ValueError("Receiver mapping descriptor join conflicts with a newer retained review")
        required = {"PreSetLocalStorage", "PostSetLocalStorage", "publisher", "merger", "localStorageSetItem",
            "callMappingEngineAction", "isElectronApp", "initialization_owner", "derived_feature_owner", "default_module_owner",
            "initial_document_factory", "runtime_identity_parameters"}
        observed = {"slave_storage_changed", "storage_listener_registration", "slave_storage_observer_startup",
            "serial_window_storage_listener", "serial_ready_republish"}
        for pid, row in reviewed.items():
            runtime = products[pid]["duallink_protocol"]["runtime_selection"]
            publication = products[pid]["duallink_protocol"]["event_selection_and_publication"]
            gate = row["suppression_gate"]
            if (row["runtime_identity"] != runtime["identity"] or row["physical_branches"] != runtime["physical_branches"]
                    or row["base_selection_review"] != section["runtime_selection_review"]
                    or row["target_execution"] or row["whole_page_complete"] or not row["source_branch_selection_complete"]
                    or row["runtime_acceptance"] != "unverified" or not row["remaining_local_chains"]
                    or gate["feature"] != "controllerDevice" or gate["active_at_current_source_startup"]
                    or gate["owner"] not in incoming or row["hash"]["implementation_owner"] not in incoming
                    or set(row["chain_owners"]) != required or set(row["slave_storage_observers"]) != observed
                    or any(key not in incoming for key in (*row["chain_owners"].values(), *row["slave_storage_observers"].values()))
                    or row["change_gate"]["report_ids_independent_trigger"]
                    or row["change_gate"]["storage_boolean_result_consumed"]
                    or row["change_gate"]["cache_rollback_on_storage_failure"]
                    or not row["change_gate"]["cache_updated_before_storage_await"]
                    or row["master_observer_feature_gate"] != runtime["gates"]["isDualLinkDevice"]["value"]
                    or row["mika_observer_feature_gate"] != runtime["gates"]["isMikaDevice"]["value"]
                    or row["wireless_physical_ids"] != [value for field in ("dongleId", "bleId")
                                                       if (value := runtime["identity"][field])]
                    or row["initial_descriptor"]["owner"] not in incoming
                    or {key: row["initial_descriptor"][key] for key in ("version", "vendorId", "productId", "category", "reportIDs")}
                       != {"version": 1, "vendorId": 5426, "productId": pid, "category": "MOUSE",
                           "reportIDs": {"4": "razerKeyReportID", "5": "hardwareEventReportID"}}
                    or len(row["master_observer_callers"]) != 1
                    or row["master_observer_callers"][0]["owner"] not in incoming
                    or len(row["master_observer_callers"][0]["gates"]) != 2
                    or any(item["owner"] not in incoming for item in row["master_observer_callers"][0]["gates"])
                    or any(row["chain_owners"][field] != publication["storage_hooks"][field]
                           for field in ("PreSetLocalStorage", "PostSetLocalStorage"))
                    or row["chain_owners"]["publisher"] not in {item["complete_owner"] for item in publication["post_storage_callers"]}):
                raise ValueError("Receiver mapping descriptor join has an incomplete or conflicting actual caller")
        existing = section["complete_owners"]
        for key, owner in incoming.items():
            if key in existing and not same_owner(existing[key], owner):
                raise ValueError("Receiver mapping descriptor join conflicts with a retained original owner")
        for key, owner in incoming.items():
            if key not in existing:
                existing[key] = deepcopy(owner)
        for pid, row in reviewed.items():
            product = products[pid]
            protocol = product["duallink_protocol"]
            publication = protocol["event_selection_and_publication"]
            publication["semantics"]["publication"] = row["semantics"]["publisher"]
            publication["semantics"]["selection_boundary"] = (
                "Current source startup, hooks, actual publisher, single-slave storage observers and native descriptor storage/classifier are joined for the five reviewed physical branches. Dynamic feature mutation, actual host-provided runtime identity, native registration/event delivery and final UI observation remain unverified; packaged alternatives are not declared active.")
            publication["mapping_descriptor_review"] = reference
            old = "Actual host-provided runtime/master identity, descriptor publication, native event producer/type/collection classification and final UI state must complete their product-specific joins; current startup adapter/parser branch selection is resolved but does not establish runtime registration or whole-page closure"
            for target in (product, protocol):
                if "unresolved_chains" in target:
                    remaining = [item for item in target["unresolved_chains"] if item != old]
                    remaining.extend(item for item in row["remaining_local_chains"] if item not in remaining)
                    target["unresolved_chains"] = remaining
        selected = {key: deepcopy(review[key]) for key in ("products", "source_sets", "host_descriptor_review",
            "host_native_original", "host_sources", "host_owners")}
        selected.update({"review_source": reference, "target_execution": False, "whole_page_complete": False,
            "rust_implementation": "unverified", "ui_backend_wiring": "unverified",
            "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified"})
        section["mapping_descriptor_contract"] = selected
        return {"products": sorted(reviewed), "complete_owners": len(incoming),
            "field": "receiver_legacy/mapping_descriptor_contract", "whole_page_complete": False}
    if review["kind"] == "current_legacy_camera_native_property_review":
        section = document["legacy_selection"]
        products = {row["product_id"]: row for row in section["products"]}
        reviewed = {row["product_id"]: row for row in review["products"]}
        if (set(reviewed) != set(CAMERA_LEGACY_PRODUCTS) or len(reviewed) != len(review["products"])
                or not reviewed.keys() <= products.keys() or review["base_selection_review"] != section["review_source"]
                or review["scope"] != ["Brightness", "CameraFocus", "Contrast", "Saturation", "WhiteBalance"]
                or review["target_execution"] or review["whole_page_complete"]):
            raise ValueError("Legacy native property review has a different selection, scope or completion boundary")
        current = section.get("native_property_contract")
        if current is not None and current.get("review_source") != reference:
            raise ValueError("Legacy native property review conflicts with a newer retained review")
        for pid, row in reviewed.items():
            native = products[pid]["native"]
            export_names = {prefix + name for prefix in ("Get", "Set") for name in
                            ("Brightness", "CameraFocus", "Contrast", "Saturation", "WhiteBalance")}
            required_functions = {"container_lookup", "video_get", "video_set", "camera_get", "camera_set",
                                  "async_camera_set", "async_camera_get", "async_video_set", "async_video_get"} | export_names
            if (row["original"] != native["original"] or row["resource_version"] != native["resource"]["resourceVersion"]
                    or row["base_selection_review"] != section["review_source"] or row["target_execution"]
                    or row["whole_native_semantics"] != "unverified" or row["official_dll_comparison"] != "not_executed"
                    or len(row["functions"]) != (27 if pid == 3592 else 25) or not required_functions <= row["functions"].keys()
                    or len(row["actual_exports"]) != 10 or {item["name"] for item in row["actual_exports"]} != export_names
                    or len(row["actual_callback_slots"]) != (8 if pid == 3592 else 4)
                    or {item["interface"] for item in row["interfaces"]} != {"IAMCameraControl", "IAMVideoProcAmp"}
                    or any(not item["actual_pe_bytes_verified"] for item in row["interfaces"])
                    or any(not item["input_chunks_verified"] for item in row["functions"].values())):
                raise ValueError("Legacy native property review has an invalid original or incomplete native binding")
        section["native_property_contract"] = {"products": copy.deepcopy(review["products"]),
            "scope": copy.deepcopy(review["scope"]), "review_source": reference,
            "target_execution": False, "whole_page_complete": False, "official_dll_comparison": "not_executed",
            "rust_implementation": "unverified", "ui_backend_wiring": "unverified", "runtime_acceptance": "unverified"}
        return {"products": sorted(reviewed), "complete_native_functions": sum(len(row["functions"]) for row in reviewed.values()),
            "field": "legacy_selection/native_property_contract", "whole_page_complete": False}
    if review["kind"] == "current_legacy_camera_selection_review":
        products = {row["product_id"]: row for row in review["products"]}
        if len(products) != len(review["products"]) or set(products) != set(CAMERA_LEGACY_PRODUCTS):
            raise ValueError("Legacy camera review must cover the exact four current products")
        if review["target_execution"] or review["whole_page_complete"]:
            raise ValueError("Static legacy camera review cannot promote runtime or whole-page completion")
        current = document.get("legacy_selection")
        if current is not None and current.get("review_source") != reference:
            raise ValueError("Legacy camera semantic review conflicts with a newer retained review")
        for pid, row in products.items():
            selected, gates = row["selection"], row["ui_gates"]
            native = row["native"]
            if (selected["device_type"] != CAMERA_LEGACY_TYPES[pid]
                    or selected["dll"] != {"name": "RzNativeDLL" + str(pid), "onDllLoaded": "startCamera"}
                    or bool(selected["camera_config"].get("isAdvancedCamera")) != (pid == 3592)
                    or gates["advanced_pages"] != (pid == 3592)
                    or gates["supports_hdr"] != (pid == 3589) or gates["supports_field_of_view"] != (pid == 3589)
                    or not row["source_branch_selection_complete"] or row["target_execution"] or row["whole_page_complete"]
                    or not row["remaining_local_chains"]
                    or native["resource"]["resourceName"] != selected["dll"]["name"]
                    or native["resource"]["sha256"].lower() != native["original"]["sha256"]
                    or native["resource"]["size"] != native["original"]["bytes"]):
                raise ValueError("Legacy camera has an invalid identity, selected branch or completion boundary")
            required = {"selected_adapter_loader", "adapter_init", "adapter_terminate", "read_standard_settings",
                        "task_focus", "task_image", "camera_dispatch", "profile_camera_restore", "ui_mounted_product"}
            if (not required <= row["chain_owners"].keys()
                    or any(key not in incoming for key in row["chain_owners"].values())
                    or any(member["owner"] not in incoming for member in row["adapter_members"].values())):
                raise ValueError("Legacy camera review is missing a complete original owner")
        selected = {key: copy.deepcopy(review[key]) for key in ("products", "source_sets", "complete_owners", "verified_artifacts")}
        selected.update({"review_source": reference, "source_branch_selection_complete": True,
            "target_execution": False, "whole_page_complete": False, "rust_implementation": "unverified",
            "ui_backend_wiring": "unverified", "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"})
        if current is not None:
            selected.update({key: copy.deepcopy(value) for key, value in current.items() if key not in selected})
        document["legacy_selection"] = selected
        return {"products": sorted(products), "complete_owners": len(incoming),
                "field": "legacy_selection", "whole_page_complete": False}
    if review["kind"] == "current_gamepad_lighting_selection_review":
        section = document["gamepad_lighting"]
        products = {row["product_id"]: row for row in section["products"]}
        reviewed = {row["product_id"]: row for row in review["products"]}
        scope = set(GAMEPAD_LIGHTING_SELECTION_PRODUCTS)
        if (len(reviewed) != len(review["products"]) or set(reviewed) != scope
                or len(products) != len(section["products"]) or not scope <= products.keys()):
            raise ValueError("Gamepad selection review must cover the exact nine current products")
        current = section.get("branch_selection")
        current_reference = current.get("review_source") if current is not None else None
        if (current is not None and current_reference is None
                or current_reference != reference and (current_reference != expected_previous_review
                    or review.get("previous_review_source") != current_reference)):
            raise ValueError("Gamepad selection review conflicts with a newer retained review")
        for product in products.values():
            branch = product.get("branch_selection")
            source_reference = product.get("source_review", {}).get("review_source")
            if (branch is not None and branch.get("review_source") != current_reference
                    or source_reference is not None and source_reference != current_reference):
                raise ValueError("Gamepad product selection conflicts with a newer retained review")
        for pid, row in reviewed.items():
            if (row["identity"]["productId"] != pid or not row["source_branch_selection_complete"]
                    or row["target_execution"] or not row["remaining_local_chains"]
                    or bool(row["controller_config"]["supportsLighting"]) != bool(row["ui_lighting_mounted"])
                    or row["obm"]["reads_controller_lighting"] != ("controllerLightingEffects" in row["default_profile_fields"])):
                raise ValueError("Gamepad selection has an invalid identity, branch or completion boundary")
            owners = [row["bootstrap_owner"], *row["chain_owners"].values(), *row["ui_mount_owners"]]
            if any(key not in incoming for key in owners):
                raise ValueError("Gamepad selection is missing a complete original owner")
        old = "Current2676 shared notification/OBM calls into extended-static helper require full indirect dispatch resolution despite the unmounted Lighting page; presence of helper bodies is not a capability proof"
        selected = {key: copy.deepcopy(review[key]) for key in ("products", "source_sets", "semantics", "complete_owners", "verified_artifacts")}
        selected.update({"review_source": reference, "source_branch_selection_complete": True,
            "target_execution": False, "whole_page_complete": False, "rust_implementation": "unverified",
            "ui_backend_wiring": "unverified", "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified"})
        if "previous_review_source" in review:
            selected["previous_review_source"] = copy.deepcopy(review["previous_review_source"])
        for pid, row in reviewed.items():
            product = products[pid]
            product["branch_selection"] = copy.deepcopy(row)
            product["branch_selection"]["review_source"] = reference
            product["unresolved_chains"] = [item for item in product["unresolved_chains"] if pid != 2676 or item != old]
            if pid == 2676:
                product.setdefault("source_review", {})["notification_branch"] = row["notification_resolution"]
                product["source_review"]["obm_branch"] = row["obm"]["semantics"]
                product["source_review"]["review_source"] = reference
        section["branch_selection"] = selected
        return {"products": sorted(reviewed), "complete_owners": len(incoming),
                "field": "gamepad_lighting/branch_selection", "whole_page_complete": False}
    if review["kind"] == "current_legacy_receiver_runtime_selection_review":
        section = document["receiver_legacy"]
        existing = section["complete_owners"]
        products = {row["product_id"]: row for row in section["products"]}
        reviewed = {row["product_id"]: row for row in review["products"]}
        if len(reviewed) != len(review["products"]) or set(reviewed) != {158, 192, 194, 211, 222}:
            raise ValueError("Receiver runtime review must cover the exact five current products")
        if not set(reviewed).issubset(products):
            raise ValueError("Receiver runtime review has no existing product audit")
        for pid, row in reviewed.items():
            selected = row["runtime_selection"]
            if (selected["identity"]["productId"] != pid or not selected["source_branch_selection_complete"]
                    or selected["target_execution"] or not row["remaining_local_chains"]):
                raise ValueError("Receiver runtime review has an invalid selection or completion boundary")
            current = products[pid]["duallink_protocol"].get("runtime_selection")
            if current is not None and current != selected:
                raise ValueError("Receiver runtime review conflicts with the retained selection")
        for key, owner in incoming.items():
            if key in existing and not same_owner(existing[key], owner):
                raise ValueError("Receiver runtime review conflicts with a retained complete owner")
        old = {"Runtime feature injection, actual adapter identity and parser overrides must be joined to each source product/version/host initialization branch; retained alternate modules alone do not establish a live selection",
               "The complete native event producer/type/collection classification and final UI state chain remain required; verified native subsets are not whole-page/native closure"}
        for key, owner in incoming.items():
            if key not in existing:
                existing[key] = copy.deepcopy(owner)
        for pid, row in reviewed.items():
            product = products[pid]
            protocol = product["duallink_protocol"]
            protocol["runtime_selection"] = copy.deepcopy(row["runtime_selection"])
            for target in (product, protocol):
                remaining = [item for item in target["unresolved_chains"] if item not in old]
                remaining.extend(item for item in row["remaining_local_chains"] if item not in remaining)
                target["unresolved_chains"] = remaining
                target["source_branch_selection_complete"] = True
                target["runtime_selection_review"] = reference
            for role, key in row["selected_chain_owners"].items():
                ref = {"role": role, "key": key}
                if ref not in protocol["complete_owners"]:
                    protocol["complete_owners"].append(ref)
        section["runtime_selection_review"] = reference
        return {"products": sorted(reviewed), "complete_owners": len(existing),
                "field": "receiver_legacy", "whole_page_complete": False}
    if review["kind"] == "current_legacy_receiver_resource_owner_review":
        if review["product_ids"] != [158, 192, 194, 211, 222]:
            raise ValueError("Receiver resource review product scope differs")
        section = document["receiver_legacy"]
        previous = section["generated_descriptors"]
        if previous not in (review["superseded_descriptor_receipts"], review["generated_descriptors"]):
            raise ValueError("Receiver generated resource owners changed after the review")
        section["generated_descriptors"] = copy.deepcopy(review["generated_descriptors"])
        section["generated_descriptor_owners"] = copy.deepcopy(review["generated_descriptor_owners"])
        section["generated_descriptor_review"] = reference
        return {"products": review["product_ids"], "generated_descriptors": len(review["generated_descriptors"]),
            "field": "receiver_legacy/generated_descriptors", "whole_page_complete": False}
    if review["kind"] == "current_747_direction_obm_semantic_review":
        if review["product_id"] != 747 or review["target_execution"] or review["whole_page_complete"]:
            raise ValueError("Keypad semantic review has an invalid product or completion boundary")
        section = document["queries"]["gamepad_tester"]
        existing = {owner["id"]: owner for owner in section["complete_owners"]}
        if len(existing) != len(section["complete_owners"]):
            raise ValueError("Retained keypad complete owners have duplicate identities")
        for key, owner in incoming.items():
            if key in existing and not same_owner(existing[key], owner):
                raise ValueError("Keypad semantic review conflicts with a retained complete owner")
        marker = section["keypad_747_review"]
        current = marker.get("direction_mode_write_and_obm")
        if isinstance(current, dict) and current.get("review_source") != reference:
            raise ValueError("Keypad semantic review conflicts with a newer retained review")
        selected = {key: copy.deepcopy(value) for key, value in review.items() if key in {
            "selection", "obm_static_dependencies", "direction_static_dependencies", "concrete_members",
            "commands", "transport_defaults", "assignment_response_parser", "direction_helpers",
            "direction_constants", "default_navigation_keys", "semantics", "remaining_local_chains"}}
        selected.update({"review_source": reference, "static_semantics": "current_selected_dependency_closure_verified",
            "rust_implementation": "unverified", "ui_backend_wiring": "unverified",
            "official_dll_comparison": "not_executed", "runtime_acceptance": "unverified",
            "whole_product_complete": False})
        for key, owner in incoming.items():
            if key not in existing:
                section["complete_owners"].append(copy.deepcopy(owner))
        marker["direction_mode_write_and_obm"] = selected
        if reference not in section["verified_artifacts"]:
            section["verified_artifacts"].append(reference)
        return {"products": [747], "complete_owners": len(section["complete_owners"]),
                "field": "queries/gamepad_tester/keypad_747_review/direction_mode_write_and_obm",
                "whole_page_complete": False}
    raise ValueError("Unsupported current frontend semantic review kind")


def publish_frontend_semantic_review(args):
    """Verify frozen bytes, then merge only the selected canonical semantic field."""
    source = getattr(args, "semantic_review", None)
    digest = getattr(args, "semantic_review_sha256", None)
    if not source or not digest or not re.fullmatch(r"[a-f0-9]{64}", digest):
        raise ValueError("Semantic publication needs a frozen review and its exact SHA-256")
    path = a.ROOT / source
    allowed = (a.ROOT / ".analysis/results/reverse-pending/review-sources").resolve()
    if not path.resolve().is_relative_to(allowed) or path.stem != digest or path.suffix != ".json":
        raise ValueError("Semantic review path is outside the retained hash-addressed review boundary")
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != digest:
        raise ValueError("Semantic review bytes differ from the reviewed SHA-256")
    review = json.loads(raw)
    if review.get("target_execution") is not False or review.get("whole_page_complete") is not False:
        raise ValueError("Static semantic publication cannot promote runtime completion")
    kinds = {"current_legacy_receiver_runtime_selection_review": ("mouse", "mouse-receiver-legacy", "mouse-main-audit.json"),
             MATCHER_NUMERIC_KIND: ("mouse", "mouse-dpi-matcher", "mouse-mw-audit.json"),
             "current_keyboard_wireless_power_review": ("keyboard", "keyboard-wireless-power", "keyboard-mw-audit.json"),
             "current_legacy_receiver_mapping_descriptor_review": ("mouse", "mouse-receiver-mapping", "mouse-main-audit.json"),
             "current_legacy_receiver_resource_owner_review": ("mouse", "mouse-receiver-legacy", "mouse-main-audit.json"),
             "current_747_direction_obm_semantic_review": ("keyboard", "keyboard-gamepad-tester", "keyboard-mw-audit.json"),
             "current_gamepad_lighting_selection_review": ("gamepad", "gamepad-lighting-selection", "gamepad-main-audit.json"),
             "current_legacy_camera_selection_review": ("accessories", "camera-legacy-selection", "accessories-camera-local-pages-audit.json"),
             "current_legacy_camera_native_property_review": ("accessories", "camera-legacy-native-properties", "accessories-camera-local-pages-audit.json")}
    if review["kind"] not in kinds:
        raise ValueError("Unsupported current frontend semantic review kind")
    family, query, destination = kinds[review["kind"]]
    if args.family != family or args.query != query or getattr(args, "prepare", False):
        raise ValueError("Semantic review publication requires its matching family/query without resource preparation")
    numeric_snapshot = None
    if review["kind"] == MATCHER_NUMERIC_KIND:
        if (args.function != "mw" or getattr(args, "receipt_only", False)
                or args.product is not None and sorted(set(args.product)) != sorted((*MATCHER_NUMERIC_PRODUCTS, 196))):
            raise ValueError("Matcher numeric publication requires the exact mouse mw product scope")
        numeric_snapshot = verify_mouse_matcher_numeric_review(review)
    originals = {}
    complete_owners = {} if numeric_snapshot is not None else review["complete_owners"]
    for key, owner in complete_owners.items():
        original = owner["original"]
        if original["path"] not in originals:
            if not valid(original):
                raise ValueError("Semantic review original bytes changed: " + original["path"])
            originals[original["path"]] = (a.ROOT / original["path"]).read_bytes()
        body = originals[original["path"]][owner["byte_start"]:owner["byte_end"]]
        if (body.decode() != owner["body"] or hashlib.sha256(body).hexdigest() != owner["body_sha256"]
                or key != ":".join((original["sha256"], str(owner["byte_start"]), str(owner["byte_end"])))):
            raise ValueError("Semantic review complete owner differs from its official original")
    if review["kind"] == "current_legacy_receiver_runtime_selection_review":
        for row in review["products"]:
            if any(not valid(row[key]) for key in ("acquisition", "base_capture")):
                raise ValueError("Receiver semantic review acquisition/capture changed")
    elif review["kind"] in {"current_747_direction_obm_semantic_review", "current_gamepad_lighting_selection_review", "current_legacy_camera_selection_review", "current_legacy_camera_native_property_review", "current_legacy_receiver_mapping_descriptor_review", "current_keyboard_wireless_power_review"}:
        if any(not valid(original) for original in review["originals"]):
            raise ValueError("Frontend semantic review source snapshot changed")
        if review["kind"] in {"current_gamepad_lighting_selection_review", "current_legacy_camera_selection_review", "current_legacy_camera_native_property_review", "current_legacy_receiver_mapping_descriptor_review", "current_keyboard_wireless_power_review"} and any(not valid(item) for item in review["verified_artifacts"]):
            raise ValueError("Frontend selection complete capture artifact changed")
    elif numeric_snapshot is None and any(not valid(item) for item in review["verified_artifacts"]):
        raise ValueError("Receiver resource owner input/output bytes changed")
    reference = {"path": a.rel(path), "bytes": len(raw), "sha256": digest}
    target = a.ROOT / ".analysis/results/frontend" / destination
    with a.index_lock():
        before = target.read_bytes()
        document = json.loads(before)
        previous_gamepad_review = None
        previous_numeric_review = None
        if numeric_snapshot is not None:
            previous_numeric_review, _ = retained_mouse_matcher_numeric_review(document)
        if review["kind"] == "current_gamepad_lighting_selection_review":
            previous_gamepad_review, _ = retained_gamepad_lighting_review(document["gamepad_lighting"])
        result = merge_frontend_semantic_review(document, review, reference,
            expected_previous_review=getattr(args, "semantic_previous_review", None))
        if target.read_bytes() != before or path.read_bytes() != raw:
            raise ValueError("Canonical audit or frozen review changed during semantic publication")
        if previous_gamepad_review is not None and not valid(previous_gamepad_review):
            raise ValueError("Retained gamepad selection review bytes changed during publication")
        if numeric_snapshot is not None:
            if (previous_numeric_review is not None and not valid(previous_numeric_review)
                    or any(not valid(item) for item in numeric_snapshot["artifacts"])):
                raise ValueError("Matcher numeric source or retained review bytes changed during publication")
            index = json.loads((a.ROOT / ".analysis/inputs.json").read_bytes())["inputs"]
            for item in numeric_snapshot["indexed_originals"]:
                matches = [row for row in index if row.get("path") == item["path"]]
                if len(matches) != 1 or any(matches[0].get(key) != item[key] for key in ("bytes", "sha256")):
                    raise ValueError("Matcher numeric indexed source identity changed during publication")
        a.save(target, document)
        published = json.loads(target.read_bytes())
        if published != document:
            raise ValueError("Published semantic review differs from the complete merged audit")
    result.update({"receipt": a.rel(target), "review_source": reference, "target_execution": False,
        "runtime_acceptance": "unverified", "cleanup": {"temporary_files_retained": [],
            "private_databases_created": [], "publication": "Shared atomic publisher released its owned staging file"}})
    print(json.dumps(result, ensure_ascii=False), flush=True)
    return result


def audit_mouse_receiver_legacy(args):
    """Read current mounted single-LED and pairing chains and prepare proved assets.

    Product bundles also contain unreachable receiver widgets. Keep complete
    callers, wrappers, reducers and MW bodies, and join the separate mounted
    multipairing application's current sources. Native closure remains explicit.
    """
    import importlib.metadata
    import sys
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    if args.family != "mouse" or args.function != "main":
        raise ValueError("mouse-receiver-legacy requires current mouse main originals")
    ids = sorted(set(args.product or [158, 192, 194, 211, 222]))
    if set(ids) - {158, 192, 194, 211, 222}:
        raise ValueError("Resolve the current mounted receiver owner before extending this query")
    # The generated runtime tables own the entire mounted legacy domain.
    # Preparing a subset must not silently drop the other product branches.
    if args.prepare:
        ids = [158, 192, 194, 211, 222]
    parser = Parser(Language(tree_sitter_javascript.language()))
    owners, rows = {}, []
    application = {"failures": [], "source_chain_complete": False, "runtime_acceptance": "unverified"}
    app_receipt_path = a.ROOT / ".analysis/inputs/frontend/synapse-multipairing-current/acquisition.json"
    app_capture_path = a.ROOT / ".analysis/results/frontend/synapse-multipairing-current/analysis.json"
    if app_receipt_path.is_file() and app_capture_path.is_file():
        try:
            app_acquired = json.loads(app_receipt_path.read_bytes())
            app_captured = json.loads(app_capture_path.read_bytes())
            if not app_acquired.get("source_current_during_acquisition") or not app_captured.get("input_bytes_unchanged"):
                raise ValueError("Separate MultiPairing deployment/capture stability is unverified")
            app_files = {item["url"]: item for item in app_acquired["files"] if item.get("path")}
            if any(not valid(item) for item in app_files.values()):
                raise ValueError("Separate MultiPairing original bytes differ")
            app_main = next(item for item in app_files.values() if re.search(r"/static/js/main\.[^/]+\.js$", item["url"]))
            app_css = next(item for item in app_files.values() if re.search(r"/static/css/main\.[^/]+\.css$", item["url"]))
            app_body = (a.ROOT / app_main["path"]).read_bytes()
            application.update({"acquisition": identity(app_receipt_path), "capture": identity(app_capture_path),
                "tool": app_captured["tool"], "complete_originals": list(app_files.values()),
                "main_capture_modules": source_capture_modules(app_captured, app_main),
                "complete_main": {"original": app_main, "byte_start": 0, "byte_end": len(app_body),
                    "body_sha256": hashlib.sha256(app_body).hexdigest(), "body": app_body.decode("utf-8")},
                "complete_css": {"original": app_css, "body": (a.ROOT / app_css["path"]).read_text(encoding="utf-8")},
                "capture_failures": [command for command in app_captured.get("commands", []) if command.get("exit_code")],
                "unresolved_acquisition": app_acquired.get("unresolved", []),
                "failed_acquisition": [item for item in app_acquired["files"] if not item.get("path")],
                "target_execution": False})
            application.update(review_current_multipairing(app_acquired, app_captured, app_files,
                app_main, app_css, parser, owners))
        except (OSError, ValueError, KeyError, StopIteration, TypeError) as error:
            application["failures"].append(str(error))
    else:
        application["failures"].append("Separate currently mounted MultiPairing application acquisition/capture is absent")

    def original_set(pid, layer):
        name = f"mouse-{'mw-' if layer == 'mw' else ''}{pid}-current"
        receipt_path = a.ROOT / f".analysis/inputs/frontend/{name}/acquisition.json"
        captured_path = a.ROOT / f".analysis/results/frontend/{name}/analysis.json"
        acquired = json.loads(receipt_path.read_bytes())
        captured = json.loads(captured_path.read_bytes())
        if not acquired.get("source_current_during_acquisition") or not captured.get("input_bytes_unchanged"):
            raise ValueError("Current deployment/capture stability is unverified: " + name)
        files = {item["url"]: item for item in acquired["files"] if item.get("path")}
        manifest_name = "webpackManifest.json" if layer == "mw" else "asset-manifest.json"
        roots = [acquired["entry_url"], urllib.parse.urljoin(acquired["entry_url"], manifest_name)]
        if layer == "mw":
            roots.append(urllib.parse.urljoin(acquired["entry_url"], "manifest.json"))
        if any(url not in files or not valid(files[url]) for url in roots):
            raise ValueError("Original entry/manifest identity differs: " + name)
        manifest = json.loads((a.ROOT / files[roots[1]]["path"]).read_bytes())
        main_url = urllib.parse.urljoin(roots[1], manifest["main.js"] if layer == "mw" else manifest["files"]["main.js"])
        html = a.References()
        html.feed((a.ROOT / files[roots[0]]["path"]).read_text(encoding="utf-8"))
        mounted = {urllib.parse.urljoin(roots[0], literal) for literal, _ in html.refs}
        if main_url not in mounted:
            raise ValueError("Original entry does not mount its main JS: " + name)
        selected = [item for url, item in files.items()
                    if f"/products/{pid}/{layer}/" in url and Path(urllib.parse.urlsplit(url).path).suffix in {".js", ".css"}]
        if any(not valid(item) for item in selected):
            raise ValueError("Current JS/CSS original bytes differ: " + name)
        return acquired, files, files[main_url], captured, {
            "acquisition": identity(receipt_path), "capture": identity(captured_path),
            "tool": captured["tool"], "complete_originals": [files[url] for url in roots] + selected,
            "capture_failures": [command for command in captured.get("commands", []) if command.get("exit_code")],
            "unresolved_acquisition": acquired.get("unresolved", []),
            "failed_acquisition": [item for item in acquired["files"] if not item.get("path")]}

    for pid in ids:
        row = {"product_id": pid, "complete_owners": [], "failures": [], "unresolved_chains": [],
               "whole_page_complete": False, "source_chain_complete": False, "runtime_acceptance": "unverified"}
        rows.append(row)
        try:
            acquired, files, main, captured, ui = original_set(pid, "ui")
            row["ui"] = ui
            trees = {}

            def parsed(source):
                if source["path"] not in trees:
                    content = (a.ROOT / source["path"]).read_bytes()
                    trees[source["path"]] = (content, parser.parse(content))
                return trees[source["path"]]

            def outer_owner(source, offset, method=False):
                content, tree = parsed(source)
                node = tree.root_node.descendant_for_byte_range(offset, offset)
                candidates = []
                while node is not None:
                    if method and node.type == "method_definition":
                        name = node.child_by_field_name("name")
                        if name and name.text.isdigit():
                            return node
                    if node.type in {"variable_declarator", "class_declaration", "function_declaration"} and node.end_byte - node.start_byte < 262144:
                        candidates.append(node)
                    node = node.parent
                if not candidates:
                    # Some current entry state machines are in an unbound
                    # webpack IIFE. Retain the complete original program rather
                    # than inventing a named owner or truncating its body.
                    return tree.root_node
                return candidates[-1]

            def keep(role, source, node):
                key = f"{source['sha256']}:{node.start_byte}:{node.end_byte}"
                if key not in owners:
                    owners[key] = {"original": source, "byte_start": node.start_byte, "byte_end": node.end_byte,
                        "node_type": node.type, "body_sha256": hashlib.sha256(node.text).hexdigest(),
                        "body": node.text.decode("utf-8"),
                        "capture_modules": source_capture_modules(captured if source == main else mw_captured, source)}
                ref = {"role": role, "key": key}
                if ref not in row["complete_owners"]:
                    row["complete_owners"].append(ref)
                return node

            def anchors(role, source, needle, method=False):
                content, _ = parsed(source)
                matches = list(re.finditer(re.escape(needle.encode("utf-8")), content))
                for match in matches:
                    keep(role, source, outer_owner(source, match.start(), method))
                return matches

            content, tree = parsed(main)
            text = content.decode("utf-8")
            # UI captures are selected separately from MW captures below.
            mw_captured = captured
            panel_matches = anchors("single_led_widget", main, 'className:"indicator-led-container"')
            row["single_led"] = {"widget_count": len(panel_matches), "mounted_calls": []}
            if panel_matches:
                panel = outer_owner(main, panel_matches[0].start())
                panel_name = panel.child_by_field_name("name").text.decode("utf-8")
                wrapper = re.search(rb'([\w$]+)=\(0,[^;]{0,240}\)\(' + re.escape(panel_name.encode()) + rb'\)', content[panel.end_byte:panel.end_byte + 500])
                unbound_connect = re.search(rb'\(0,[^;]{0,240}\)\(' + re.escape(panel_name.encode()) + rb'\)', content[panel.end_byte:panel.end_byte + 500])
                if wrapper is None and (pid != 222 or unbound_connect is None):
                    raise ValueError("Single-LED connected wrapper is unresolved")
                wrapper_offset = panel.end_byte + (wrapper or unbound_connect).start()
                if wrapper is not None:
                    keep("single_led_connected_wrapper", main, outer_owner(main, wrapper_offset))
                    name = wrapper[1]
                    calls = list(re.finditer(rb'(?:jsx|jsxs)\)\(' + re.escape(name) + rb',', content))
                else:
                    node = tree.root_node.descendant_for_byte_range(wrapper_offset, wrapper_offset)
                    while node is not None and node.type != "expression_statement":
                        node = node.parent
                    keep("single_led_unbound_connect_expression", main, node)
                    name, calls = None, []
                for match in calls:
                    caller = keep("single_led_mounted_caller", main, outer_owner(main, match.start()))
                    row["single_led"]["mounted_calls"].append({"byte_offset": match.start(),
                        "owner_start": caller.start_byte, "context": content[max(0, match.start() - 160):match.end() + 160].decode("utf-8")})
                row["single_led"].update({"binding": panel_name, "wrapper": name.decode() if name else None,
                    "unbound_connect_expression": name is None,
                    "reachability": "mounted" if calls else "no JSX mount of the connected wrapper in the current complete main input"})
                # Preserve every inline SVG variant, including unselected props.
                svg_names = set(re.findall(rb'(?:jsx|jsxs)\)\(([\w$]+),\{\}\)', panel.text))
                stack = [tree.root_node]
                while stack:
                    node = stack.pop()
                    name_node = node.child_by_field_name("name") if node.type == "variable_declarator" else None
                    if name_node and name_node.text in svg_names and 0 < panel.start_byte - node.start_byte < 100000:
                        keep("single_led_inline_svg_variant", main, node)
                    stack.extend(reversed(node.children))
                anchors("single_led_modes", main, "Connection_Status:1,Battery_Status:2,Battery_Warning:3")
                anchors("single_led_reducer_response_persistence", main, 'postMessage({type:"ON_SET_INDICATOR_LED"')
                export = re.search(rb'setIndicatorLedStatus:\(\)=>([\w$]+)', content)
                if export:
                    action = re.search(rb'(?<![\w$])' + re.escape(export[1]) + rb'=e=>async', content)
                    if action:
                        keep("single_led_action", main, outer_owner(main, action.start()))

                if calls:
                    import workspace
                    import evidence as e
                    # Default mounted callers pass no custom SVG/title props.
                    # Resolve copy through the widget's actual namespace import.
                    def copy_key(expression):
                        namespace, export_name = expression.split(".")
                        resolved = e.javascript_binding(content, tree, namespace, panel.start_byte)
                        if resolved["resolution"] != "declaration":
                            raise ValueError("Single-LED copy namespace is unresolved")
                        binding = content[resolved["start_byte"]:resolved["end_byte"]]
                        module_match = re.fullmatch(rb'[\w$]+=[\w$]+\((\d+)\)', binding)
                        if module_match is None:
                            raise ValueError("Single-LED copy namespace is not a current module import")
                        module_matches = list(re.finditer(rb'(?<![\w$])' + module_match[1] + rb'(?=[(:])', content))
                        modules = {}
                        for match in module_matches:
                            node = tree.root_node.descendant_for_byte_range(match.start(), match.start())
                            while node is not None:
                                name = node.child_by_field_name("key") if node.type == "pair" else node.child_by_field_name("name") if node.type == "method_definition" else None
                                if name is not None and name.text == module_match[1] and node.start_byte == match.start():
                                    modules[node.start_byte] = node
                                    break
                                node = node.parent
                        if len(modules) != 1:
                            raise ValueError("Single-LED copy module is absent/ambiguous")
                        module = next(iter(modules.values()))
                        keep("single_led_complete_copy_module", main, module)
                        exports = list(re.finditer(re.escape(export_name.encode()) + rb':\(\)=>([\w$]+)(?=[,}])', module.text))
                        if len(exports) != 1:
                            raise ValueError("Single-LED copy export is absent/ambiguous")
                        at = module.start_byte + exports[0].start()
                        value = e.javascript_binding(content, tree, exports[0][1].decode(), at)
                        declaration = content[value["start_byte"]:value["end_byte"]].decode()
                        return json.loads(declaration.split("=", 1)[1])
                    widget = panel.text.decode()
                    expressions = {
                        "title": re.search(r'customTitle\?this\.props\.customTitle:([\w$]+\.[\w$]+)', widget)[1],
                        "description": re.search(r'className:"indicator-description".*?text:([\w$]+\.[\w$]+)', widget)[1],
                        "disabled_tooltip": re.search(r'\(0,[\w$]+\.[\w$]+\)\(([\w$]+\.[\w$]+),\{_lang:', widget)[1],
                    }
                    option_rows = []
                    for mode, identifier, custom in ((1, "connectionstatus", "customConnectionStatus"),
                                                     (2, "batterystatus", "customDesBatteryStatus"),
                                                     (3, "batterywarning", "customDesBatteryWarning")):
                        label = re.search(r'name:([\w$]+\.[\w$]+),id:"' + identifier + '"', widget)[1]
                        description = re.search(custom + r'\?this\.props\.' + custom + r':([\w$]+\.[\w$]+)', widget)[1]
                        option_rows.append({"mode": mode, "id": identifier, "label": copy_key(label), "description": copy_key(description)})
                    svg_names = re.findall(r'return\(0,[\w$]+\.jsx\)\(([\w$]+),\{\}\)', widget)[-3:]
                    if len(svg_names) != 3:
                        raise ValueError("Single-LED default mounted SVG branches are incomplete")
                    resources = []
                    modes = []
                    for mode, name in enumerate(svg_names, 1):
                        refs = [ref for ref in row["complete_owners"] if ref["role"] == "single_led_inline_svg_variant"
                                and owners[ref["key"]]["body"].startswith(name + "=")]
                        if len(refs) != 1:
                            raise ValueError("Single-LED mounted SVG complete declaration is unresolved")
                        owner = owners[refs[0]["key"]]
                        anchor = owner["body"][:owner["body"].index('"svg"')]
                        module = workspace.complete_resource_module(text, anchor)
                        specification = {"anchor": anchor, "module_id": module["module_id"], "svg_index": 0, "opacity_layer": "base"}
                        _, derivation = workspace.static_jsx_svg(text, specification)
                        prefix = f"synapse/mouse-receiver-legacy/{pid}-{mode}"
                        resources.append({"display": prefix + "-base.svg", "inline_jsx_svg": specification})
                        layers = []
                        for layer in derivation["source_opacity_layers"]:
                            alias = prefix + "-" + layer["id"] + ".svg"
                            resources.append({"display": alias, "inline_jsx_svg": {**specification, "opacity_layer": layer["id"]}})
                            layers.append({**layer, "image": alias})
                        modes.append({"mode": mode, "base": prefix + "-base.svg", "layers": layers})
                    row["single_led_descriptor"] = {"product_id": pid,
                        **{key: copy_key(value) for key, value in expressions.items()}, "options": option_rows, "modes": modes}
                    row["single_led_resource_request"] = {"acquisition": f".analysis/inputs/frontend/mouse-{pid}-current/acquisition.json",
                        "resources": {main["path"]: resources}}

            top_names = {158: "VL", 192: "VA", 194: "ML", 211: "AO", 222: "qO"}
            top_match = re.search(rb'class ' + top_names[pid].encode() + rb' extends ', content)
            if top_match is None:
                raise ValueError("Current TopView binding differs from the audited mount")
            top = keep("mounted_top_view_and_feature_lifecycle", main, outer_owner(main, top_match.start()))
            if pid == 194:
                row["pairing"] = {"source_declares_multipairing": False,
                    "evidence": "No isMultiPairingSupported, global.multipairing or multiDevicePairingInit in complete current main"}
            else:
                component_names = {158: "YL", 192: "yA", 211: "IO", 222: "ZO"}
                component_match = re.search(rb'(?<![\w$])' + component_names[pid].encode() + rb'=e=>', content)
                component = outer_owner(main, component_match.start())
                keep("multipairing_launch_panel", main, component)
                # Complete contiguous helpers include master/slave resolution,
                # localStorage normalization, timers and window-service launch.
                region_start = max(0, component.start_byte - 15000)
                stack = [tree.root_node]
                covered_end = region_start
                while stack:
                    node = stack.pop()
                    if node.end_byte <= region_start or node.start_byte >= component.end_byte:
                        continue
                    if node.type in {"variable_declarator", "class_declaration", "function_declaration"} and region_start <= node.start_byte and node.end_byte <= component.end_byte:
                        if node.start_byte >= covered_end:
                            keep("multipairing_complete_local_helper", main, node)
                            covered_end = node.end_byte
                        continue
                    stack.extend(reversed(node.children))
                anchors("multipairing_frame_route_parameters_messages_cleanup", main, "/synapse/multipairing/")
                anchors("multipairing_frame_route_parameters_messages_cleanup", main, "multiDevicePairingInit")
                anchors("multipairing_route_selector", main, '"multiDevicePairing"===')
                row["pairing"] = {"source_declares_multipairing": True,
                    "feature": "global.multipairing -> provisionFlags; complete TopView body retains branch gates",
                    "application_url": "https://apps.razer.com/synapse/multipairing/",
                    "application_originals_retained": "complete_main" in application and not application["failures"]}
                if not row["pairing"]["application_originals_retained"]:
                    row["unresolved_chains"].append("Separate currently mounted /synapse/multipairing/ application original JS/CSS/manifest/resource closure has not verified; product iframe wrapper is not the whole application")
                if pid in {211, 222}:
                    fallback_names = {211: ("BT", "vT"), 222: ("FI", "BI")}
                    for fallback in fallback_names[pid]:
                        match = re.search(rb'(?<![\w$])' + fallback.encode() + rb'=', content[5000000:])
                        keep("legacy_duallink_fallback_and_dialog", main, outer_owner(main, 5000000 + match.start()))
                    # Retain every complete declaration in the old fallback
                    # subtree, including scanner views, confirmation and SVGs.
                    fallback_end = next(owners[ref["key"]]["byte_end"] for ref in row["complete_owners"]
                        if ref["role"] == "legacy_duallink_fallback_and_dialog")
                    region_start = fallback_end - 30000
                    stack = [tree.root_node]
                    while stack:
                        node = stack.pop()
                        if node.end_byte <= region_start or node.start_byte >= fallback_end:
                            continue
                        if node.type in {"variable_declarator", "class_declaration", "function_declaration"} and region_start <= node.start_byte and node.end_byte <= fallback_end:
                            keep("legacy_duallink_complete_subtree", main, node)
                            continue
                        stack.extend(reversed(node.children))

            css_rows = [source for source in files.values() if source["url"].endswith(".css") and f"/products/{pid}/ui/" in source["url"]]
            row["complete_css_rules"] = []
            for source in css_rows:
                css = (a.ROOT / source["path"]).read_text(encoding="utf-8")
                for match in re.finditer(r'[^{}]+\{[^{}]*\}', css):
                    if any(token in match[0].split("{", 1)[0].lower() for token in ("indicator-", "connectionstatus", "batterystatus", "batterywarning", "multipair", "duallink", "duallinker")):
                        row["complete_css_rules"].append({"original": source, "character_offset": match.start(), "body": match[0]})
            row["resource_closure"] = [{"reference": edge, "original": files.get(edge.get("to"))}
                for edge in acquired.get("edges", []) if any(token in str(edge).lower() for token in ("multipair", "duallink", "indicator"))]

            mw_acquired, mw_files, mw_main, mw_captured, mw = original_set(pid, "mw")
            row["mw"] = mw
            mw_sources = [source for source in mw_files.values()
                if source["url"].endswith(".js") and f"/products/{pid}/mw/" in source["url"]
                and not Path(source["path"]).name.startswith(("translations", "service-worker"))]
            needles = {
                "mw_indicator_event_dispatch_and_flags": 'case"ON_SET_INDICATOR_LED"',
                "mw_indicator_taskmaker_profile_persistence": "taskMakerSetIndicatorLed",
                "mw_indicator_runner_response": "taskRunner set indicator led SUCCESS",
                "mw_indicator_device_wrapper": "setIndicatorLedConfiguration(e){",
                "mw_indicator_runtime_getter": "getIndicatorLedConfiguration();",
                "mw_indicator_state_machine_permission_dispatch": "ONSTORAGE_FAIL_MACRO_RECORDER_RUNNING",
                "mw_indicator_state_machine_permission_guards": "macroRecorderNotRunning:()=>!window.macroRecorderExclusiveHeld",
                "mw_indicator_runtime_serial_query": "Queried serial number is empty, set to ",
                "mw_indicator_runtime_serial_sentinel": '="NOSERIALNUMBER"',
                "mw_indicator_actual_slave_role_gate": 'initDualLink() failed',
                "mw_indicator_feature_registration": 'useFeature("supportIndicatorLed","config"',
                "mw_indicator_feature_default_parameters": 'useFeature=(e,t,n)=>',
                "mw_indicator_hid_export_module": "Vw:()=>",
                "mw_duallink_scan_bind_unbind_response_cleanup_and_storage": "DUALLINK_SCAN_DEVICE:",
                "mw_duallink_device_scan_adapter": "deviceScan(e){",
                "mw_duallink_device_pair_adapter": "setDevicePairingMode(e",
                "mw_duallink_device_unpair_adapter": "setDeviceUnpair(e",
            }
            counts = Counter()
            for source in mw_sources:
                body = (a.ROOT / source["path"]).read_bytes()
                for role, needle in needles.items():
                    if needle.encode() in body:
                        matches = anchors(role, source, needle, method="export_module" in role or "duallink_scan_bind" in role)
                        counts[role] += len(matches)
            row["mw_anchor_counts"] = dict(counts)
            if pid in {158, 192, 194}:
                registrations = []
                for source in mw_sources:
                    body = (a.ROOT / source["path"]).read_bytes()
                    registrations.extend(re.finditer(
                        rb'useFeature\("supportIndicatorLed","config"(,\{disableInDuallinkSlave:!0\})?\)', body))
                if len(registrations) != 1:
                    raise ValueError("Actual single-LED startup registration is absent/ambiguous")
                row["initial_indicator_getter_enabled"] = bool(registrations[0][1])
                if row["initial_indicator_getter_enabled"] != (pid in {158, 192}):
                    raise ValueError("Current single-LED startup config changed; review complete setup chain")
            if not counts["mw_duallink_scan_bind_unbind_response_cleanup_and_storage"]:
                raise ValueError("Complete current MW DualLink handler module is unresolved")
            try:
                row["duallink_protocol"] = review_legacy_duallink_protocol(pid, mw_files, mw_captured, parser, owners)
                if "single_led_transport" in row["duallink_protocol"]:
                    row["duallink_protocol"]["single_led_transport"]["initial_indicator_getter_enabled"] = row["initial_indicator_getter_enabled"]
            except (OSError, ValueError, KeyError, StopIteration, TypeError, AttributeError) as error:
                row["duallink_protocol"] = {"failures": [str(error)], "source_chain_complete": False,
                    "whole_page_complete": False, "unresolved_chains": ["The independently compiled product's actual module/export imports require continued resolution: " + str(error)]}
            row["unresolved_chains"].extend(row["duallink_protocol"]["unresolved_chains"])
            row["semantics"] = {
                "single_led_visibility": "158 mounts directly when dongle; 192 additionally suppresses macro and disables while pairedInfo is nonempty; 194 always mounts its connected widget and disables its parent when isDongle===false; 211 has no widget; 222's packaged widget has an unbound connect result and no JSX wrapper mount",
                "multipairing_visibility": "158/192 require isMultiPairingSupported, provisionFlags and slave helper; 211/222 use provisionFlags and otherwise mount the complete old DualLink subtree",
                "launch": "Resolve duallink-devices master; query actual WindowService clients/container; focus existing master page or construct sameWindow/autofocus route with allMasters; preserve fallback and console-only failure",
                "device_state": "Indicator optimistic reducer, MW local profile persistence, runner outcome and runtime dongle getter are distinct complete owners",
                "permissions": "Generic w/k dispatch permits UI/runtime/device events to save then write when the macro recorder does not hold exclusive access; local-profile events write without re-saving. While recording only updateLocalStorage is permitted, but the actual indicator taskMaker is wholly gated by deviceAccess, so it performs neither persistence nor SET nor MW UI publication. The initial runtime getter remains a separate preceding query.",
                "serial": "Protocol getSerialNumber has no request payload. Its complete u parser keeps every ASCII byte 32..126, skipping embedded control bytes; runtime se returns NOSERIALNUMBER only for a successful empty query and returns an empty string on query rejection. The dongle setup serial gate consumes that distinction.",
                "slave_gate": "The setup's actual UZ/J role helper reads ordered Object.values of duallink-devices, uses exact deviceContainerId and the first record matching dongleId or master.dongleId, and classifies SLAVE when that record's dongleId matches. This is a local-cache role decision, separate from the packaged queryDualLinkInfo method; no extra hardware primary-device read is introduced.",
                "startup_getter": "Complete startup registration configures disableInDuallinkSlave=true for 158/192, but 194 passes no parameter and useFeature defaults it to {}. Setup requires config.disableInDuallinkSlave && !isSlave before its GET, so 194 never runs this startup GET. Profile reload and explicit setter callers remain separate.",
                "binding_info": "PID192 TopView.componentDidMount registers MW_RESPONSE_UI, asks DUALLINK_BIND_INFO, and consumes payload before checking error. Current he requests live statusV2, filters 65535 and own193, joins exact-container USB role and current AvailableDevices/DualDongleCompatibleDevices plus connectedDeviceInfo. Rejection explicitly publishes [] with its error; it is distinct from a successful empty read.",
                "cleanup": "Complete retained component useEffect/componentWillUnmount bodies are evidence; no invented listener cleanup or ACK rollback",
                "scope": "Current-source static query with optional source-derived resource preparation. Product implementation and static/simulated validation are tracked independently; whole-page and real-device acceptance remain incomplete."}
        except (OSError, ValueError, KeyError, StopIteration, TypeError, AttributeError) as error:
            row["failures"].append(str(error))
    host_native = review_legacy_host_native()
    report_path = a.ROOT / ".analysis/results/frontend/mouse-main-audit.json"
    # Other receiver audits share the file; reload immediately before writing.
    report = json.loads(report_path.read_bytes()) if report_path.is_file() else {"schema_version": 1}
    binding_transports = [transport for row in rows
        for transport in row.get("duallink_protocol", {}).get("binding_query_transports", [])]
    report["receiver_legacy"] = {"recorded_at_utc": a.stamp(), "tool": identity(Path(__file__)),
        "parser": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
        "products": rows, "complete_owners": owners, "multipairing_application": application,
        "binding_query_transports": binding_transports,
        "host_native": host_native, "product_code_modified": False,
        "prepared_product_resources_modified": False, "target_execution": False, "runtime_acceptance": "unverified"}
    a.save(report_path, report)
    if args.prepare and not any(row["failures"] or row.get("duallink_protocol", {}).get("failures") for row in rows):
        import workspace
        preparations = [row["single_led_resource_request"] for row in rows if "single_led_resource_request" in row]
        report["receiver_legacy"]["resource_preparation"] = workspace.prepare_resources(preparations)
        descriptors = [row["single_led_descriptor"] for row in rows if "single_led_descriptor" in row]
        transports = [row["duallink_protocol"]["single_led_transport"] for row in rows
                      if "single_led_transport" in row.get("duallink_protocol", {})]
        data_path = a.builtin_data_path("razer-pages", "MOUSE_RECEIVER_LEGACY_DATA")
        transport_path = a.builtin_data_path("razer-device", "MOUSE_RECEIVER_LEGACY_CAPABILITIES")
        binding_transport_path = a.builtin_data_path("razer-device", "MOUSE_BINDING_QUERY_CAPABILITIES")
        a.save(data_path, descriptors)
        a.save(transport_path, transports)
        a.save(binding_transport_path, binding_transports)
        report["receiver_legacy"]["generated_descriptors"] = [identity(data_path), identity(transport_path), identity(binding_transport_path)]
        report["receiver_legacy"]["prepared_product_resources_modified"] = True
        a.save(report_path, report)
    print(json.dumps({"receipt": a.rel(report_path), "products": len(rows), "complete_owners": len(owners),
        "failures": [{"product_id": row["product_id"], "failures": row["failures"]} for row in rows if row["failures"]],
        "application_failures": application["failures"],
        "protocol_failures": [{"product_id": row["product_id"], "failures": row.get("duallink_protocol", {}).get("failures", [])}
                              for row in rows if row.get("duallink_protocol", {}).get("failures")],
        "unresolved_chains": [{"product_id": row["product_id"], "items": row["unresolved_chains"]} for row in rows]}), flush=True)
    if application["failures"] or any(row["failures"] or row.get("duallink_protocol",{}).get("failures") for row in rows):
        raise ValueError("Current legacy receiver source capture remains unresolved")


def review_camera_task_scheduling(report, selected):
    """Resolve current task makers to their real named queues and runners."""
    import evidence as e
    import importlib.metadata
    import sys
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    parser = Parser(Language(tree_sitter_javascript.language()))
    owners, products = {}, []

    for product in report["products"]:
        pid = product["product_id"]
        if pid not in selected:
            continue
        acquired_path = a.ROOT / product["layers"]["mw"]["acquisition"]["path"]
        captured_path = a.ROOT / product["layers"]["mw"]["capture"]["path"]
        acquired = json.loads(acquired_path.read_bytes())
        captured = json.loads(captured_path.read_bytes())
        if not acquired.get("source_current_during_acquisition") or not captured.get("input_bytes_unchanged"):
            raise ValueError("Current camera scheduler deployment/capture is unverified: " + str(pid))
        originals = {source["path"]: source for source in acquired["files"] if source.get("path")}
        capture_inputs = {source["path"]: source for source in captured["original_inputs"]}
        sources, parsed = [], {}
        for source in originals.values():
            if not valid(source):
                raise ValueError("Camera scheduler original bytes differ: " + source["path"])
            if not source["path"].endswith(".js"):
                continue
            if capture_inputs.get(source["path"]) != {key: source[key] for key in ("path", "bytes", "sha256")}:
                raise ValueError("Camera scheduler capture original differs: " + source["path"])
            sources.append(source)
        row = {"product_id": pid, "acquisition": identity(acquired_path), "capture": identity(captured_path),
               "complete_owners": [], "export_resolutions": [], "lifecycle_callers": [],
               "searched_originals": sources, "capture_failures": [command for command in captured.get("commands", []) if command.get("exit_code")],
               "unresolved_acquisition": acquired.get("unresolved", []), "source_chain_complete": False,
               "whole_page_complete": False, "runtime_acceptance": "unverified"}
        products.append(row)

        def tree_for(source):
            if source["path"] not in parsed:
                raw = (a.ROOT / source["path"]).read_bytes()
                tree = parser.parse(raw)
                if tree.root_node.has_error:
                    raise ValueError("Camera scheduler JavaScript parse errors: " + source["path"])
                parsed[source["path"]] = (raw, tree)
            return parsed[source["path"]]

        def module_at(source, start, end=None):
            _, tree = tree_for(source)
            node = tree.root_node.descendant_for_byte_range(start, end or start)
            while node is not None:
                key = node.child_by_field_name("key") if node.type == "pair" else node.child_by_field_name("name") if node.type == "method_definition" else None
                if key is not None and key.type == "number":
                    return node
                node = node.parent
            raise ValueError("Camera scheduler webpack module boundary is unresolved")

        def keep(role, source, node, source_capture=None):
            key = f"{source['sha256']}:{node.start_byte}:{node.end_byte}"
            owners.setdefault(key, {"original": source, "byte_start": node.start_byte, "byte_end": node.end_byte,
                "node_type": node.type, "body": node.text.decode("utf-8"),
                "body_sha256": hashlib.sha256(node.text).hexdigest(), "capture_modules": source_capture_modules(source_capture or captured, source)})
            ref = {"role": role, "key": key}
            if ref not in row["complete_owners"]:
                row["complete_owners"].append(ref)
            return key

        def resolve_export(source, module, exported, role):
            matches = list(re.finditer(re.escape(exported.encode()) + rb':\(\)=>([\w$]+)', module.text))
            if len(matches) != 1:
                raise ValueError("Camera scheduler export is absent/ambiguous: " + exported)
            match = matches[0]
            name, at = match[1].decode(), module.start_byte + match.start()
            raw, tree = tree_for(source)
            resolved = e.javascript_binding(raw, tree, name, at)
            if resolved["resolution"] != "declaration":
                raise ValueError("Camera scheduler export binding is unresolved: " + exported)
            node = tree.root_node.descendant_for_byte_range(resolved["start_byte"], resolved["end_byte"] - 1)
            while node is not None and (node.start_byte != resolved["start_byte"] or node.end_byte != resolved["end_byte"] or node.type != resolved["syntax"]):
                node = node.parent
            if node is None or module_at(source, node.start_byte).start_byte != module.start_byte:
                raise ValueError("Camera scheduler export resolves outside its module: " + exported)
            key = keep(role, source, node)
            resolution = {"export": exported, "binding": name,
                "reference_byte": at, "module_start": module.start_byte, "complete_owner": key}
            if node.type == "variable_declarator" and node.child_by_field_name("value") is None:
                initializers = list(re.finditer(re.escape(name.encode()) + rb'\|\|\(' + re.escape(name.encode()) + rb'=\{\}\)', module.text))
                if len(initializers) != 1:
                    raise ValueError("Camera scheduler enum initialization is absent/ambiguous: " + exported)
                offset = module.start_byte + initializers[0].start()
                initializer = tree.root_node.descendant_for_byte_range(offset, offset)
                while initializer is not None and initializer.type != "call_expression":
                    initializer = initializer.parent
                if initializer is None:
                    raise ValueError("Camera scheduler complete enum initializer is unresolved: " + exported)
                resolution["complete_initialization"] = keep(role + "_initialization", source, initializer)
            row["export_resolutions"].append(resolution)
            return node

        exposure_ref = next(ref for ref in product["complete_owners"] if ref["role"] == "mw_exposure_task")
        exposure = report["complete_owners"][exposure_ref["key"]]
        source = originals[exposure["original"]["path"]]
        raw, _ = tree_for(source)
        if raw[exposure["byte_start"]:exposure["byte_end"]].decode("utf-8") != exposure["body"]:
            raise ValueError("Camera scheduler task maker no longer matches complete source bytes")
        maker = module_at(source, exposure["byte_start"])
        keep("complete_exposure_task_maker_module", source, maker)
        manager_aliases = set(re.findall(r'([\w$]+)\.RzTaskManager\.enqueueTask', exposure["body"]))
        runner_aliases = set(re.findall(r'NORMAL_SKIPPABLE,([\w$]+)\.p5A\.', exposure["body"]))
        if len(manager_aliases) != 1 or len(runner_aliases) != 1:
            raise ValueError("Camera scheduler task maker imports are unresolved")

        imports = {}
        for role, alias in (("task_manager", next(iter(manager_aliases))), ("task_runner", next(iter(runner_aliases)))):
            imported = list(re.finditer(rb'(?<![\w$])' + re.escape(alias.encode()) + rb'=n\((\d+)\)', maker.text))
            if len(imported) != 1:
                raise ValueError("Camera scheduler actual import is absent/ambiguous: " + alias)
            imports[role] = {"alias": alias, "webpack_module": int(imported[0][1]),
                             "reference_byte": maker.start_byte + imported[0].start()}
        row["task_maker_imports"] = imports

        modules = {}
        for role, imported in imports.items():
            matches = []
            pattern = re.compile(rb'(?<![\w$])' + str(imported["webpack_module"]).encode() + rb':\(e,t,n\)=>')
            for candidate in sources:
                body = (a.ROOT / candidate["path"]).read_bytes()
                for match in pattern.finditer(body):
                    node = module_at(candidate, match.start())
                    if node.start_byte == match.start():
                        matches.append((candidate, node))
            if len(matches) != 1:
                raise ValueError("Camera scheduler imported module is absent/ambiguous: " + str(imported["webpack_module"]))
            modules[role] = matches[0]
            keep("complete_" + role + "_module", *matches[0])
        manager_source, manager = modules["task_manager"]
        for exported in ("RzTaskManager", "RzTaskCategory"):
            resolve_export(manager_source, manager, exported, "scheduler_" + exported)
        runner_source, runner = modules["task_runner"]
        for exported, role in (("p5A", "task_names"), ("pe1", "auto_exposure_runner"), ("w$_", "auto_exposure_result"),
                               ("N0J", "exposure_value_runner"), ("mQT", "exposure_value_result"),
                               ("Wcp", "shutter_speed_runner"), ("NjB", "shutter_speed_result"),
                               ("zEU", "focus_compound_runner"), ("EE_", "focus_compound_result"),
                               ("DtK", "image_compound_runner"), ("Y61", "image_compound_result"),
                               ("sj7", "denoise_compound_runner"), ("RUn", "denoise_compound_result")):
            resolve_export(runner_source, runner, exported, role)

        # The third-party picker uses the generic feature handler, rather than
        # the dedicated exposure task-maker module. Retain both full owners.
        for role, needle, kinds in (
            ("generic_autoframing_handler", b'featureKey="CAMERA_AUTOFRAMING"', {"class", "class_declaration"}),
            ("generic_feature_task_maker", b'static taskMakerHandler(', {"method_definition"}),
        ):
            matches = {}
            for candidate in sources:
                raw, tree = tree_for(candidate)
                for match in re.finditer(re.escape(needle), raw):
                    node = tree.root_node.descendant_for_byte_range(match.start(), match.end())
                    while node is not None and node.type not in kinds:
                        node = node.parent
                    if node is None or node.has_error:
                        raise ValueError("Camera generic complete owner is unresolved: " + role)
                    matches[(candidate["sha256"], node.start_byte)] = (candidate, node)
            if len(matches) != 1:
                raise ValueError("Camera generic complete owner is absent/ambiguous: " + role)
            candidate, node = next(iter(matches.values()))
            keep(role, candidate, node)
            keep("complete_" + role + "_module", candidate, module_at(candidate, node.start_byte))

        # Resolve the actual hook used by this product's mounted preview. Name
        # spellings differ across the three independently compiled products.
        ui_acquired_path = a.ROOT / product["layers"]["ui"]["acquisition"]["path"]
        ui_capture_path = a.ROOT / product["layers"]["ui"]["capture"]["path"]
        ui_acquired = json.loads(ui_acquired_path.read_bytes())
        ui_capture = json.loads(ui_capture_path.read_bytes())
        if not ui_acquired.get("source_current_during_acquisition") or not ui_capture.get("input_bytes_unchanged"):
            raise ValueError("Current camera focus deployment/capture is unverified")
        ui_inputs = {item["path"]: item for item in ui_capture["original_inputs"]}
        ui_originals = {item["path"]: item for item in ui_acquired["files"] if item.get("path")}
        preview_ref = next(ref for ref in product["complete_owners"] if ref["role"] == "ui_preview")
        preview = report["complete_owners"][preview_ref["key"]]
        ui_source = ui_originals[preview["original"]["path"]]
        if not valid(ui_source) or ui_inputs.get(ui_source["path"]) != {key: ui_source[key] for key in ("path", "bytes", "sha256")}:
            raise ValueError("Current camera focus original/capture identity differs")
        ui_raw, ui_tree = tree_for(ui_source)
        if ui_raw[preview["byte_start"]:preview["byte_end"]].decode("utf-8") != preview["body"]:
            raise ValueError("Mounted camera preview source differs")

        def ui_binding(name, at, role):
            resolved = e.javascript_binding(ui_raw, ui_tree, name, at)
            if resolved["resolution"] != "declaration":
                raise ValueError("Camera host focus binding is unresolved: " + role)
            node = ui_tree.root_node.descendant_for_byte_range(resolved["start_byte"], resolved["end_byte"] - 1)
            while node is not None and (node.start_byte != resolved["start_byte"] or node.end_byte != resolved["end_byte"] or node.type != resolved["syntax"]):
                node = node.parent
            if node is None:
                raise ValueError("Camera host focus complete owner is unresolved: " + role)
            keep(role, ui_source, node, ui_capture)
            return node

        hook_match = re.search(r'l=([\w$]+)\("synapse",window.name\)', preview["body"])
        if hook_match is None:
            raise ValueError("Mounted camera preview host focus caller is unresolved")
        hook = ui_binding(hook_match[1], preview["byte_start"] + hook_match.start(1), "ui_host_focus_hook")
        helper_match = re.search(rb'([\w$]+)\(e,E\)\.then', hook.text)
        if helper_match is None:
            raise ValueError("Camera host focus status helper caller is unresolved")
        ui_binding(helper_match[1].decode(), hook.start_byte + helper_match.start(1), "ui_host_focus_status_helper")
        row["ui_focus_inputs"] = {"acquisition": identity(ui_acquired_path), "capture": identity(ui_capture_path), "original": ui_source}

        # Keep complete current lifecycle callers; do not infer cancellation
        # from a product-side queue or from the task-manager API's availability.
        for candidate in sources:
            body = (a.ROOT / candidate["path"]).read_bytes()
            for match in re.finditer(rb'([\w$]+)\.RzTaskManager\.(init|cancelAllTasks|cancelTask)\(', body):
                module = module_at(candidate, match.start())
                if module.start_byte == manager.start_byte and candidate == manager_source:
                    continue
                imported = re.search(rb'(?<![\w$])' + re.escape(match[1]) + rb'=n\(' + str(imports["task_manager"]["webpack_module"]).encode() + rb'\)', module.text)
                if imported is None:
                    raise ValueError("Camera scheduler lifecycle manager import is unresolved")
                _, tree = tree_for(candidate)
                node = tree.root_node.descendant_for_byte_range(match.start(), match.end())
                local = []
                while node is not None and node.start_byte != module.start_byte:
                    if node.type in {"function_declaration", "variable_declarator", "class_declaration"}:
                        local.append(node)
                    node = node.parent
                owner = local[-1] if local else module
                key = keep("task_manager_" + match[2].decode() + "_caller", candidate, owner)
                row["lifecycle_callers"].append({"method": match[2].decode(), "byte_offset": match.start(), "complete_owner": key})
        row["semantics"] = {
            "queue_ownership": "RzTaskManager.taskMap is keyed by source task name; each queue has one currentTask, pendingTask and cancellingTask. getWebLockName joins the initialized container identifier and that task name, so distinct task names use distinct exclusive Web Locks.",
            "enqueue": "enqueueTask pushes then immediately calls run. With no current task, NORMAL_SKIPPABLE pops the newest pending task and starts it; a newly enqueued task never automatically cancels the current task.",
            "coalescing": "After the current task settles, nextTaskScheduler schedules setTimeout before run. That run selects pending.pop(), reports the first skipped pending task with skip(false), later skipped tasks with skip(true), disposes them and runs the newest with its skipped flag true. NORMAL queues shift FIFO instead.",
            "cancellation": "cancelTask moves an active task into cancellingTask, aborts its controller and clears currentTask; a pending cancellation reports error 'canceled'. AbortError from a Web Lock reports 'aborted'. cancelAllTasks aborts current tasks and reports cancellation/disposal for pending tasks; the complete callers above define where it is actually used.",
            "completion": "Task.run always invokes resultClosure in finally; settledHandler disposes and schedules pending work. The exposure/shutter runners check abort before the device method, retain result/error, and their exported result closures only log the source outcome.",
            "manual_exposure": "The source exposure-value and shutter-speed tasks share p5A.shutterSpeed. The auto-exposure enable task uses p5A.autoExposure. A previously started exposure-value task may run before a later shutter-speed task; only tasks still pending at the next run are skipped. A fixed 500ms caller delay does not prove the earlier task completed.",
            "implementation": "CameraIntentQueue reserves a current slot on enqueue for each actual source task name, retains its current task while coalescing pending tasks, and uses a separate service worker plus container/name Windows mutex. Exposure mode/companions remain separate tasks; focus/image remain compound runners. The native-method mutex separately serializes standard calls and complete ISP exchanges.",
            "source_false_results": "Complete focus, image and denoise runners ignore individual native false results and continue later calls unless the runner throws. Rust retains a failed receipt and continues the same audited compound; it does not manufacture a device ACK.",
            "host_focus": "The actual mounted preview hook resolves its own full status helper. Initial/focus(false) checks window visibility/minimized status and the selected host tab; activeTabChanged updates selection directly. F's start gate checks the selected tab independently of OS activation.",
            "generic_autoframing": "The complete CAMERA_AUTOFRAMING handler persists the full object. Disable restores stored zoom/pan/tilt even after native false; enable sends configured speed/size only after success. Generic taskMakerHandler enqueues one NORMAL_SKIPPABLE task under the feature key."}
        row["unresolved_chains"] = ["Actual asynchronous device/service latency and cross-tab Web Lock contention are not established by static source; no final device-state equivalence is inferred", "Complete source queue semantics do not establish the complete mounted camera page, native ABI closure or runtime acceptance"]
    return {"tool": identity(Path(__file__)),
            "parser": {name: importlib.metadata.version(name) for name in ("tree-sitter", "tree-sitter-javascript")},
            "products": products, "complete_owners": owners, "target_execution": False, "runtime_acceptance": "unverified"}


def native_rip_u32_initializers(assembly, start, count):
    """Read x64 RIP-relative immediate stores from already byte-verified bodies."""
    values = {}
    for instruction in assembly:
        encoded = bytes.fromhex(instruction["bytes"])
        if len(encoded) != 10 or encoded[:2] != b"\xc7\x05":
            continue
        address = int(instruction["address"], 0)
        target = address + 10 + int.from_bytes(encoded[2:6], "little", signed=True)
        if start <= target < start + count * 4:
            if (target - start) % 4 or target in values:
                raise ValueError("Native initializer contains an unaligned or duplicate target")
            values[target] = int.from_bytes(encoded[6:10], "little")
    if len(values) != count:
        raise ValueError("Native initializer does not cover its complete source table")
    return [values[start + index * 4] for index in range(count)]


def hanbo_sensor_source(audit):
    """Verify the actual external SDK selection and sensor virtual dispatch."""
    index = json.loads(audit.artifact(a.ROOT / ".analysis/inputs.json"))
    matches = [row for row in index["inputs"]
               if row["path"].startswith(".analysis/inputs/host-current/extracted/")
               and row["path"].endswith("/cpuidsdk64.dll")]
    if len(matches) != 1:
        raise ValueError("The current external sensor SDK original is absent or ambiguous")
    original = matches[0]
    audit.read(original)
    acquisition_path = a.ROOT / ".analysis/inputs/host-current/acquisition.json"
    acquisition = json.loads(audit.artifact(acquisition_path))
    packages = [row for row in acquisition["files"] if row["path"] == original["container"]
                and row["sha256"] == original["container_sha256"]]
    if len(packages) != 1:
        raise ValueError("Current external SDK acquisition container is unresolved")
    package = packages[0]
    declaration = package["declaration"]
    if (declaration["sha256"].lower() != package["sha256"]
            or declaration["size"] != package["bytes"] or declaration["url"] != package["url"]):
        raise ValueError("External SDK package differs from its official declaration")
    audit.artifact(a.ROOT / package["path"], package)
    def declares(value):
        if isinstance(value, dict):
            return value == declaration or any(declares(child) for child in value.values())
        return isinstance(value, list) and any(declares(child) for child in value)
    manifests = []
    for name in package["release_manifests"]:
        entry = next(row for row in index["inputs"] if row["path"] == name)
        release = json.loads(audit.read(entry))
        resources = [row for row in acquisition["files"] if row.get("release_manifest") == name
                     and row.get("release") == release.get("latest")]
        if len(resources) != 1:
            raise ValueError("Current SDK release resource manifest is absent or ambiguous")
        resource = resources[0]
        if (not resource["url"].endswith("/" + release["baseURL"] + "/" + release["latest"]["url"])
                or not declares(json.loads(audit.artifact(a.ROOT / resource["path"], resource)))):
            raise ValueError("Current release manifest does not declare the external SDK package")
        manifests.append({"release": entry, "resources": resource})
    if not manifests:
        raise ValueError("External SDK package has no current release manifest")
    extraction_path = a.ROOT / ".analysis/results/host-current/inspection.json"
    extraction = json.loads(audit.artifact(extraction_path))
    containers = [row for row in extraction["containers"]
                  if row["input"] == package["path"] and row["sha256"] == package["sha256"]]
    if (len(containers) != 1 or not containers[0].get("extracted")
            or containers[0].get("extraction_exit_code") != 0 or original not in containers[0]["files"]):
        raise ValueError("External SDK complete static extraction receipt is unresolved")
    provenance = {"original": original, "official_package": package,
                  "release_manifests": manifests, "acquisition": identity(acquisition_path),
                  "extraction": identity(extraction_path)}
    roles = {
        0x2499e0: "selector_xor_key_initializer", 0x2499f0: "selector_table_initializer",
        0x1aebb0: "dll_main_xor_once_384_entries_with_64_word_key",
        0x110580: "query_interface_selector_dispatch", 0x110520: "create_sdk_owner",
        0x110500: "destroy_sdk_owner_virtual_destructor",
        0x3200: "sdk_destructor_list_and_owned_buffer",
        0x1b4600: "initialize_driver_cpu_gpu_and_monitor_owners",
        0x1b4500: "close_sdk_owners", 0x1b4340: "refresh_actual_device_sensor_owners",
        0x1ab710: "visible_device_list_and_count", 0x1b1a90: "visible_device_class",
        0x1b1760: "count_valid_kind_sensors", 0x1b1660: "read_sensor_fields_and_byte_bstr",
        0x13b090: "select_valid_sensor_in_native_order", 0x13b140: "count_valid_sensors",
        0x1b1510: "reset_selected_sensor_min_max", 0x1b1440: "get_sensor_by_identifier",
        0x1b1080: "cpu_gpu_device_identifier", 0xa9d90: "device_backend_refresh_dispatch",
        0xbc950: "cpu_clock_sensor_updates", 0xadac0: "gpu_usage_sensor_updates",
        0xac440: "gpu_driver_sensor_updates", 0x1ba400: "hardware_monitor_owner_initialization",
        0xb8290: "hardware_monitor_constructor", 0xb8b70: "hardware_monitor_source_branches_and_initial_refresh",
        0xb8320: "hardware_monitor_periodic_refresh", 0xb75a0: "hardware_monitor_stop_each_backend",
        0xb87e0: "hardware_monitor_platform_branch_constructors", 0xb1a10: "display_api_monitor_priority_order",
        0x1f5170: "display_api_monitor_constructor", 0x1f50a0: "display_api_monitor_destructor",
        0x1f53d0: "display_api_sensor_queries_and_observed_sensor_creation",
        0x1fc530: "display_api_monitor_initial_read_and_result",
        0x11f680: "nvapi_platform_owner_constructor", 0x120540: "nvapi_system_library_initialize_enumerate_and_match",
        0x11f2c0: "nvapi_temperature_query_and_sleeping_adapter_status",
        0x11d3e0: "nvapi_temperature_capabilities_and_q8_8_read",
        0x11d2d0: "nvapi_thermal_settings_target_selection", 0xfbd0: "nvapi_thermal_settings_driver_dispatch",
        0x11f8e0: "nvapi_clock_versions_and_present_flags",
        0x11d7f0: "nvapi_unload", 0x11d7b0: "nvapi_reinitialize",
        0xba7f0: "display_interface_refresh", 0x139f10: "display_clock_provider_order_and_current_selection",
    }
    # Each tuple is the selector observed in current RzSystemService 0x46b0,
    # its current SDK wrapper and the CPUIDSDK_DLL virtual byte offset.
    selected = (
        (417477060, 0x1104c0, 16, 0x1b4500),
        (3969505587, 0x110450, 24, 0x1b4340),
        (2368412246, 0x110470, 32, 0x1aeac0),
        (1902699217, 0x1104e0, 8, 0x1b4600),
        (4189188963, 0x110380, 1104, 0x1ab710),
        (3141236342, 0x110360, 1112, 0x1b1a90),
        (3349516107, 0x110340, 1120, 0x1b19e0),
        (1265800933, 0x110320, 1128, 0x1b18d0),
        (4128238623, 0x110280, 1168, 0x1b1760),
        (2544578390, 0x110200, 1176, 0x1b1660),
        (3052760042, 0x1101a0, 1192, 0x1b1510),
        (2000612989, 0x110180, 1200, 0x1b1440),
        (3115676522, 0x1101c0, 1184, 0x1b1590),
        (1522185589, 0x110130, 1232, 0x1b1080),
        (2108619613, 0x110430, 48, 0x1aeaa0),
        (2741978846, 0x110410, 56, 0x1b4230),
        (3487801287, 0x1103f0, 64, 0x1b4110),
        (3459226719, 0x1103a0, 72, 0x1b3fc0),
    )
    slots = [{"role": "sdk_destructor", "vtable_rva": 0x3037c8,
              "slot_byte_offset": 0, "target_rva": 0x3200}]
    for table, offset, target in (
        (0x30c7b0, 0, 0xb8b70), (0x30c7b0, 8, 0xb75a0),
        (0x309ed8, 32, 0x1f53d0), (0x309ed8, 80, 0x1fc530),
        (0x307c08, 8, 0x120540), (0x307c08, 16, 0x11d7f0),
        (0x307c08, 24, 0x11d7b0), (0x307c08, 64, 0x11f2c0), (0x307c08, 152, 0x11f8e0),
    ):
        slots.append({"role": roles[target], "vtable_rva": table,
                      "slot_byte_offset": offset, "target_rva": target})
    for selector, wrapper, offset, target in selected:
        roles[wrapper] = "selector_" + str(selector) + "_wrapper"
        roles.setdefault(target, "selector_" + str(selector) + "_implementation")
        slots.append({"role": roles[target], "vtable_rva": 0x3037c8,
                      "slot_byte_offset": offset, "target_rva": target})
    retained = verify_native_functions(original, roles, slots, exports={"QueryInterface": 0x110580})
    bodies = {int(row["capture"]["rva"], 0): row["capture"]
              for row in retained["complete_selected_functions"]}
    keys = native_rip_u32_initializers(bodies[0x2499e0]["assembly"], 0x18038e1c0, 64)
    encoded = native_rip_u32_initializers(bodies[0x2499f0]["assembly"], 0x18038e2c0, 384)
    decoded = [value ^ keys[index % 64] for index, value in enumerate(encoded)]
    dispatch, compare_address = {}, None
    for instruction in bodies[0x110580]["assembly"]:
        code = bytes.fromhex(instruction["bytes"])
        address = int(instruction["address"], 0)
        if len(code) == 6 and code[:2] == b"\x3b\x0d":
            compare_address = address + 6 + int.from_bytes(code[2:], "little", signed=True)
        elif len(code) == 7 and code[:3] in (b"\x48\x8d\x05", b"\x48\x8d\x15"):
            index = (compare_address - 0x18038e2c0) // 4 if compare_address is not None else -1
            if not 0 <= index < len(decoded) or compare_address % 4:
                raise ValueError("SDK QueryInterface selector target is outside its initialized table")
            dispatch[decoded[index]] = address + 7 + int.from_bytes(code[3:], "little", signed=True) - 0x180000000
    for selector, wrapper, _, _ in selected:
        if dispatch.get(selector) != wrapper:
            raise ValueError("Current SDK selector no longer resolves the service sensor wrapper")
    if dispatch.get(620775936) != 0x110520 or dispatch.get(910584972) != 0x110500:
        raise ValueError("Current SDK construction/destruction selector is unresolved")
    return {**provenance, "native": retained,
        "decoded_selector_dispatch": [{"selector": key, "wrapper_rva": hex(value)}
                                      for key, value in sorted(dispatch.items())],
        "source_sensor_contract": "Device count freezes the current visible-device order; device class strips bit31. Sensor count and selection require the source sensor IsValid virtual predicate and kind mask0x3ff000. Sensor getter returns native id, SysAllocStringByteLen name, raw/current/min/max from fields328/336/348/352/356. Current values are produced by upstream refresh; resolving the getter does not establish a real sensor read.",
        "acquisition_scope": "This is the external cpuidsdk64.dll 1.3.7.6 selected from RazerAppEngine cpuz by RzSystemService0x46b0, not the separately bundled cpuidsdk64_v1.3.2.6.dll resource.",
        "gpu_driver_branch": "Display API monitors query temperature target1 first and append the GPU sensor only after a successful actual result. NVAPI branch0x11f2c0 first classifies driver return -220, then attempts capability-selected Q8.8 temperatures through selectors197662269/1711159981, then source thermal-settings selector3814984278. Clock branch0x11f8e0 uses source version retries and per-domain presence flags; source negative sentinels are not measurements. Device discovery/provider priority, complete clock refresh consumers, CPU/other GPU branches and Rust integration still require completion.",
        "remaining": ["Complete each CPU/GPU sensor creation and update branch through actual system or driver calls, including failures, cancellation and cleanup, then independently implement the backend; SDK getter/selector verification alone is not completion"],
        "target_execution": False, "runtime_acceptance": "unverified"}


def hanbo_native_inventory(audit, inputs, wrapper, *, prepare=False):
    """Project observed installed-resource identities into the existing catalog."""
    import host
    manifest_path = ".analysis/inputs/host-current/blobs/47feea84a40638fbe9f5091a896d878251f2593d39921c89fb26dd589f75f4f8/manifest-1.0.136.json"
    manifest = json.loads(audit.artifact(a.ROOT / manifest_path))
    names = {"RzSystemCommon", "RzSystemService", "RzDLLService", "cpuidsdk64Common"}
    resources = {row["resourceName"]: row for row in manifest["resources"] if row["resourceName"] in names}
    if set(resources) != names:
        raise ValueError("Current local system-monitor resource closure is incomplete")
    root = audit.tree(wrapper).root_node
    windows_module = next(row for row in keyboard_source_modules(audit.read(wrapper).decode("utf-8"))
                          if row["module_id"] == 68623)
    marker = audit.read(wrapper).index(b'this.name="rzSystemCommon"', windows_module["byte_start"], windows_module["byte_end"])
    cls = root.descendant_for_byte_range(marker, marker)
    while cls.type not in {"class", "class_declaration"}:
        cls = cls.parent
    node, key = audit.callable_member("mw_system_common_init_and_ffi_declarations", wrapper, cls, "init")
    text = node.text.decode("utf-8")
    api = {}
    for name in ("r", "c"):
        at = re.search(r'\b' + name + r'=\{', text).end() - 1
        api.update(static_js_literal(text[at:javascript_delimited(text, at)]))
    receipt = {"path": wrapper["path"], "offset": node.start_byte, "end": node.end_byte,
               "sha256": wrapper["sha256"], "source": text}
    rows, originals = [], []
    for name in sorted(names):
        resource = resources[name]
        filename = Path(urllib.parse.urlparse(resource["url"]).path).name
        expected = resource["sha256"].lower()
        matches = [row for row in inputs.values() if Path(row["path"]).name == filename and row["sha256"] == expected]
        if not matches:
            raise ValueError("Current installed system-monitor binary was not retained: " + name)
        original = sorted(matches, key=lambda row: row["path"])[0]
        raw = audit.read(original)
        if len(raw) != resource["size"] or resource["path"] != "RzDLLService" or resource["action"]["saveToDisk"]["filePath"] != "":
            raise ValueError("Current system-monitor manifest length or installation branch differs")
        pe = host.inspect_pe(raw)
        relative = "common/RzDLLService/" + filename
        rows.append({"id": name, "kind": "device" if name == "RzSystemCommon" else "engine",
            "channel": "ConfigureFFI" if name == "RzSystemCommon" else "RzDLLService",
            "file_names": [filename], "path_rules": ["apps_common"], "products": [3893],
            "declared_functions": [{"name": function, "returns": signature[0], "args": signature[1], "calls": []}
                                   for function, signature in api.items()] if name == "RzSystemCommon" else [],
            "receipts": [receipt] if name == "RzSystemCommon" else [], "sessions": [],
            "resources": [{"file": filename, "bytes": len(raw), "sha256": expected,
                "md5": hashlib.md5(raw).hexdigest(), "machine": int(pe["machine"], 0) if isinstance(pe["machine"], str) else pe["machine"],
                "exports": sorted(export for entry in pe["exports"] for export in entry["names"]),
                "bindings": [{"product_id": product, "install_relative_path": relative}
                             for product in (None, 3893)]}]})
        originals.append({"resource_name": name, "manifest_resource": resource,
                          "original": audit.sources[original["path"]], "install_relative_path": relative})
    path = a.ROOT / ".analysis/inputs/typed-tables/razer-catalog/native_library_inventory.json"
    document = json.loads(path.read_bytes())
    document["libraries"] = sorted([row for row in document["libraries"] if row["id"] not in names] + rows,
                                   key=lambda row: row["id"].lower())
    if prepare:
        a.save(path, document)
    return {"manifest": audit.artifacts[manifest_path], "resources": originals,
            "complete_wrapper": key, "catalog_source": identity(path), "prepared": prepare,
            "catalog_rows_match": all(row in json.loads(path.read_bytes())["libraries"] for row in rows)}


def verify_woff_sfnt_fixture(original, fixture):
    """Prove all source font tables survive WOFF decompression without execution."""
    import struct
    import sys
    import zlib

    def read(raw, fmt, offset):
        if offset < 0 or offset + struct.calcsize(fmt) > len(raw):
            raise ValueError("Font directory exceeds input bytes")
        return struct.unpack_from(fmt, raw, offset)

    def checksum(raw):
        padded = raw + b"\0" * (-len(raw) % 4)
        return sum(struct.unpack(">" + "I" * (len(padded) // 4), padded)) & 0xffffffff

    signature, flavor, length, count, reserved, sfnt_size = read(original, ">4sIIHHI", 0)
    fixture_flavor, fixture_count = read(fixture, ">IH", 0)
    if (signature != b"wOFF" or length != len(original) or reserved != 0 or not 0 < count <= 4096
            or fixture_flavor != flavor or fixture_count != count or sfnt_size != len(fixture)):
        raise ValueError("WOFF and sfnt headers disagree")
    expected, observed, source_spans, fixture_spans = {}, {}, [], []

    def retain(raw, tag, offset, size, directory_end, spans):
        if offset % 4 or offset < directory_end or size <= 0 or offset + size > len(raw):
            raise ValueError("Font table exceeds its retained byte boundary")
        if any(offset < end and start < offset + size for start, end in spans):
            raise ValueError("Font table byte ranges overlap")
        spans.append((offset, offset + size))
        return raw[offset:offset + size]

    for index in range(count):
        tag, offset, compressed, size, digest = read(original, ">4sIIII", 44 + index * 20)
        if tag in expected or compressed > size or size > 64 * 1024 * 1024:
            raise ValueError("WOFF table identities or lengths are invalid")
        body = retain(original, tag, offset, compressed, 44 + count * 20, source_spans)
        if compressed < size:
            decoder = zlib.decompressobj()
            body = decoder.decompress(body, size + 1)
            if not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:
                raise ValueError("WOFF compressed table is incomplete or exceeds its length")
        if len(body) != size:
            raise ValueError("WOFF original table length differs")
        if tag == b"head":
            if len(body) < 12:
                raise ValueError("Font head table has no checksum adjustment")
            body = body[:8] + b"\0" * 4 + body[12:]
        if checksum(body) != digest:
            raise ValueError("WOFF original table checksum differs")
        expected[tag] = (digest, body)
        tag, digest, offset, size = read(fixture, ">4sIII", 12 + index * 16)
        if tag in observed:
            raise ValueError("sfnt repeats a table identity")
        body = retain(fixture, tag, offset, size, 12 + count * 16, fixture_spans)
        if tag == b"head":
            if len(body) < 12:
                raise ValueError("Font head table has no checksum adjustment")
            body = body[:8] + b"\0" * 4 + body[12:]
        observed[tag] = (digest, body)
    if expected != observed:
        raise ValueError("sfnt fixture differs from the complete WOFF table set")
    if checksum(fixture) != 0xb1b0afba:
        raise ValueError("sfnt whole-file checksum adjustment differs")
    return {"tables": len(expected), "complete_table_bytes_equal": True,
            "head_checksum_adjustment_only": True, "sfnt_whole_file_checksum_verified": True,
            "tools": {"python": sys.version.split()[0], "zlib": zlib.ZLIB_RUNTIME_VERSION},
            "verification": "Static WOFF table decompression and complete sfnt table comparison; no target font code executed"}


def hanbo_page_source_review(audit, ui, css, roles, ui_set):
    curve = audit.owners[roles["ui_curve_editor"][0]]["body"]
    if not all(token in curve for token in ('e.font="14px Roboto"', 'e.translate(0,Fg-c/2)',
            'e.rotate(-Math.PI/2)', 'e.textAlign="center"', 'e.textBaseline="top"', '},[l])',
            '},[y,m,G])', 'toFixed(1)')):
        raise ValueError("Current Hanbo canvas or locale cleanup semantics changed")
    css_raw = audit.read(css)
    selectors = {'roboto_regular': '@font-face', 'disabled_contents': '.body-widgets .widget.disabled>div',
        'preset': '.sliderChart__preset-list div', 'hover': '.sliderChart__preset-list div:hover',
        'active': '.sliderChart__preset-list div.active,.sliderChart__preset-list div:active'}
    rules = {}
    for match in re.finditer(rb'([^{}]+)\{([^{}]*)\}', css_raw):
        selector = match[1].decode('utf-8')
        for name, expected in selectors.items():
            if selector == expected and (name != 'roboto_regular' or b'font-weight:400' in match[2] and b'Roboto-Regular.woff' in match[2]):
                if name in rules:
                    raise ValueError("Hanbo presentation source selector is ambiguous: " + name)
                rules[name] = {"byte_start": match.start(), "byte_end": match.end(),
                    "sha256": hashlib.sha256(match[0]).hexdigest(), "complete_rule": match[0].decode('utf-8')}
    if set(rules) != set(selectors):
        raise ValueError("Hanbo presentation source selectors are incomplete")
    if (not all(token in rules['preset']['complete_rule'] for token in ('height:27px', 'min-width:90px',
            'padding:6px 16px 7px', 'font-size:12px', 'line-height:14px', 'white-space:nowrap',
            'transition:border-color .3s,background-color .3s'))
            or 'opacity:.3;pointer-events:none' not in rules['disabled_contents']['complete_rule']
            or not rules['hover']['byte_start'] < rules['active']['byte_start']):
        raise ValueError("Hanbo preset or disabled CSS semantics changed")
    acquisition = json.loads(audit.artifact(a.ROOT / ui_set['acquisition']['path'], ui_set['acquisition']))
    font = [row for row in acquisition['files'] if row.get('path')
            and row.get('url') == 'https://apps.razer.com/synapse/assets/fonts/Roboto-Regular.woff']
    if len(font) != 1:
        raise ValueError("Hanbo source Roboto font is absent or ambiguous")
    fixture = a.ROOT / 'crates/razer-assets/testdata/rotated_label/Roboto-Regular.ttf'
    fixture_identity = identity(fixture)
    equivalence = verify_woff_sfnt_fixture(audit.read(font[0]), fixture.read_bytes())
    implementation = [identity(a.ROOT / name) for name in (
        'crates/razer-pages/src/features/accessories/accessory_system_products/hanbo_cooler.rs',
        'crates/razer-pages/src/features/accessories/accessory_system_products/hanbo_cooler_tests.rs',
        'crates/razer-pages/src/features/workspace/source_workspace.rs',
        'crates/razer-assets/src/rotated_label.rs', 'crates/razer-assets/src/rotated_label/tests.rs')]
    return {"source_review": {"source_owners": {name: roles[name] for name in ('ui_curve_editor', 'ui_fan_controls', 'ui_pump_controls')},
        "ui_original": audit.sources[ui['path']], "css_original": audit.sources[css['path']], "complete_css_rules": rules,
        "axis_titles": "yg uses 14px Roboto, centered text and top baseline after translate(0,Fg-c/2) and -PI/2 rotation. Current fan/pump grids place the rotated label at y164.5; chart right edges are510/512 and top9.",
        "locale_cleanup": "The label callback depends on language l and the canvas effect depends on[y,m,G]. A locale change runs cleanup that submits visible points rounded to one decimal; Rust retains unrounded visible geometry and drag state, submits mounted Fans then Pump once per locale change, and leaves unmounted curves alone.",
        "page_cleanup": "CH.renderView mounts only the selected navigation component. Leaving Performance for Help must unmount yg and submit the last visible points before discarding its drag and retained label. The Rust Help branch calls the same AccessorySystemProductWorkspace.set_page owner used by normal page navigation; late drag/release has no editor, and returning mounts the saved curve afresh.",
        "mode_presentation": "Preset height27px/min90px/padding6px16px7px/font12px/line14px; border and background transition independently for300ms with CSS ease. Selected and active rules follow hover, so selected background takes priority. Disabled interiors have opacity0.3 and no pointer input while the opaque#111card remains. Fans skip unchanged mode; Pump still dispatches.",
        "rust_implementation": {"inputs": implementation,
            "lifecycle": "Mounted Advanced CurveEditor retains LabelState and subscriptions. Assets obtains the cached source font and shapes text into path-only SVG on the background executor; request identity includes text, locale, geometry and actual font bytes. Cancellation and identity reject stale completion. Rendering only composes retained state; diagnostics do not dispatch source settings actions."},
        "runtime_acceptance": "unverified", "all_language_fallback_visual_acceptance": "unverified",
        "whole_page_complete": False},
        "fixtures": [{"fixture": fixture_identity, "original": audit.sources[font[0]['path']],
            "source_acquisition": ui_set['acquisition'],
            "conversion": "WOFF to sfnt with all original tables retained; only sfnt directory and head checksumAdjustment are rebuilt",
            "equivalence": equivalence, "scope": "Pure rotated-label outline tests; not a product runtime resource"}]}


def hanbo_runtime_flag_ast(parser, defaults, reducer, service, event_binding):
    """Bound the current flag to its actual initializer and payload writers."""
    import evidence

    def parse(raw, wrapper):
        raw = raw.encode("utf-8") if isinstance(raw, str) else raw
        tree = parser.parse(wrapper[0] + raw + wrapper[1])
        if tree.root_node.has_error:
            raise ValueError("Hanbo runtime flag owner has invalid JavaScript")
        return tree

    def walk(node):
        yield node
        for child in node.named_children:
            yield from walk(child)

    def fields(node):
        if node is None or node.type != "object":
            raise ValueError("Hanbo runtime payload is not a static object")
        result = {}
        for pair in node.named_children:
            if pair.type != "pair":
                raise ValueError("Hanbo runtime payload has a spread or dynamic field")
            key, value = pair.child_by_field_name("key"), pair.child_by_field_name("value")
            if key.type != "property_identifier" or key.text.decode() in result:
                raise ValueError("Hanbo runtime payload has duplicate or computed fields")
            result[key.text.decode()] = value
        return result

    default_tree = parse(defaults, (b"const ", b";"))
    default_declarations = [node for node in walk(default_tree.root_node) if node.type == "variable_declarator"]
    if len(default_declarations) != 1:
        raise ValueError("Hanbo UI runtime initializer is ambiguous")
    initial = fields(default_declarations[0].child_by_field_name("value"))
    if list(initial) != ["runtimeData"]:
        raise ValueError("Hanbo UI runtime initializer changed")
    ui_fields = fields(initial["runtimeData"])
    expected_fields = ["cpuTemp", "cpuSpeed", "fanSpeed", "pumpSpeed", "liquidTemp", "gpuTemp", "gpuSpeed"]
    if (list(ui_fields) != expected_fields + ["isHardwareOutdated"] or
            any(ui_fields[key].text != b"0" for key in expected_fields) or
            ui_fields["isHardwareOutdated"].text != b"!1"):
        raise ValueError("Hanbo hardware flag is no longer the local false initializer")

    reducer_tree = parse(reducer, (b"const ", b";"))
    reducer_nodes = list(walk(reducer_tree.root_node))
    reducer_expected = (
        b'FC=(e,E)=>{if(null!==e&&void 0!==e||(e=BC),E.type===se.B8N){'
        b'const a=(0,g.A)((0,g.A)({},e.runtimeData),E.payload);'
        b'return(0,g.A)((0,g.A)({},e),{},{runtimeData:a})}return e}')
    declarations = [node for node in reducer_nodes if node.type == "variable_declarator" and
                    node.child_by_field_name("name").text == b"FC"]
    if len(declarations) != 1 or declarations[0].text != reducer_expected:
        raise ValueError("Hanbo runtime merge/default/other-action behavior changed")

    service_raw = service.encode("utf-8") if isinstance(service, str) else service
    wrapped = b"({" + service_raw + b"})"
    tree = parse(service_raw, (b"({", b"})"))
    nodes = list(walk(tree.root_node))
    dependency_names = {}
    for name, expected in ((b"o", b"o=n(67061)"), (b"a", b"a=n(47399)")):
        imports = [node for node in nodes if node.type == "variable_declarator" and
                   node.child_by_field_name("name").text == name and node.text == expected]
        if len(imports) != 1:
            raise ValueError("Hanbo runtime event or broadcast dependency changed")
        dependency_names[name] = imports[0].child_by_field_name("name")
    declarations = [node for node in nodes if node.type == "variable_declarator" and
                    node.child_by_field_name("name").text == b"c"]
    if len(declarations) != 1:
        raise ValueError("Hanbo runtime state declaration is absent or shadowed")
    state = declarations[0]
    state_fields = fields(state.child_by_field_name("value"))
    if list(state_fields) != expected_fields:
        raise ValueError("Hanbo service adds or removes a runtime field")
    expected_values = [b'"0"', b'"0"', b"0", b"0", b"0", b'"0"', b'"0"']
    if [state_fields[key].text for key in expected_fields] != expected_values:
        raise ValueError("Hanbo service initial values changed")
    bindings = evidence.JavascriptBindings(wrapped, tree)
    state_name = state.child_by_field_name("name")
    references = [node for node in nodes if node.type == "identifier" and node.text == b"c"]
    if any(bindings.resolve("c", node.start_byte).get("start_byte") != state_name.start_byte
           for node in references):
        raise ValueError("Hanbo runtime state has an unresolved or shadowed reference")
    allowed = {state_name.start_byte}
    assignments = [node for node in nodes if node.type == "assignment_expression" and
                   node.child_by_field_name("left").text == b"c"]
    projections = []
    for assignment in assignments:
        right = assignment.child_by_field_name("right")
        if right.type != "call_expression" or right.child_by_field_name("function").text != b"Object.assign":
            raise ValueError("Hanbo runtime assignment is not the observed closed merge")
        args = right.child_by_field_name("arguments").named_children
        if len(args) != 2 or args[0].type != "call_expression":
            raise ValueError("Hanbo runtime assignment has an external state source")
        nested = args[0]
        previous = nested.child_by_field_name("arguments").named_children
        if (nested.child_by_field_name("function").text != b"Object.assign" or len(previous) != 2 or
                previous[0].text != b"{}" or previous[1].type != "identifier" or previous[1].text != b"c"):
            raise ValueError("Hanbo runtime assignment does not preserve its own prior state")
        projection = fields(args[1])
        projections.append({key: value.text.decode() for key, value in projection.items()})
        allowed.update((assignment.child_by_field_name("left").start_byte, previous[1].start_byte))
    expected_projections = [
        {"fanSpeed": "e", "pumpSpeed": "t", "liquidTemp": "n"},
        {"cpuTemp": "null==e?void 0:e.toFixed(1)", "cpuSpeed": "a",
         "gpuTemp": "null==n?void 0:n.toFixed(1)", "gpuSpeed": "l"}]
    if projections != expected_projections:
        raise ValueError("Hanbo runtime callback projections changed")
    emitters = [node for node in nodes if node.type == "variable_declarator" and
                node.child_by_field_name("name").text == b"v"]
    if (len(emitters) != 1 or
            emitters[0].text != b'v=()=>{(0,a.a)({type:o.B8N,payload:c},!1)}'):
        raise ValueError("Hanbo runtime emitter changes the event or payload")
    for node in walk(emitters[0]):
        if node.type == "identifier" and node.text in dependency_names:
            if (bindings.resolve(node.text.decode(), node.start_byte).get("start_byte") !=
                    dependency_names[node.text].start_byte):
                raise ValueError("Hanbo runtime emitter dependency is shadowed")
    payload = next(node for node in walk(emitters[0]) if node.type == "pair" and
                   node.child_by_field_name("key").text == b"payload")
    allowed.add(payload.child_by_field_name("value").start_byte)
    if {node.start_byte for node in references} != allowed:
        raise ValueError("Hanbo runtime state escapes through an unreviewed reference")
    event_tree = parse(event_binding, (b"const ", b";"))
    event_nodes = [node for node in walk(event_tree.root_node) if node.type == "variable_declarator"]
    if len(event_nodes) != 1 or event_nodes[0].child_by_field_name("value").text != b'"MW_UPDATE_DEVICE_RUNTIMEDATA"':
        raise ValueError("Hanbo runtime event identity changed")
    return {"ui_initial_hardware_outdated": False, "ui_initial_value_is_device_observation": False,
        "service_runtime_fields": expected_fields, "service_callback_projections": projections,
        "service_state_reference_count": len(references), "service_flag_producer_present": False,
        "event": "MW_UPDATE_DEVICE_RUNTIMEDATA", "missing_payload_flag_preserves_prior_value": True,
        "external_payload_flag_would_be_merged": True, "firmware_comparison_in_selected_flow": False,
        "hardware_outdated_observation": "unobserved", "target_execution": False}


def verify_hanbo_runtime_flag(document):
    """Re-read exact AST owners independently of the runtime-flow collector."""
    import host
    audit = host.HostLocalAudit()
    flow = document["hardware_outdated_flow"]
    if (flow.get("schema_version") != 1 or flow.get("target_execution") is not False or
            flow.get("runtime_acceptance") != "unverified"):
        raise ValueError("Hanbo runtime flag acceptance boundary changed")
    expected = {"ui_defaults": document["roles"]["ui_runtime_defaults"][0],
        "ui_reducer": document["roles"]["ui_runtime_reducer"][0],
        "mw_service": document["complete_modules"]["48290"],
        "mw_event": document["roles"]["mw_runtime_event_identity"][0],
        "ui_event": document["roles"]["ui_runtime_event_identity"][0],
        "ui_event_namespace": document["roles"]["ui_runtime_event_namespace"][0]}
    if flow.get("owners") != expected:
        raise ValueError("Hanbo runtime flag owner selection changed")
    bodies = {}
    for role, key in expected.items():
        owner = document["complete_owners"][key]
        raw = audit.read(owner["original"])
        fragment = raw[owner["byte_start"]:owner["byte_end"]]
        if (fragment.decode("utf-8") != owner["body"] or
                hashlib.sha256(fragment).hexdigest() != owner["body_sha256"]):
            raise ValueError("Hanbo runtime flag owner differs from original bytes")
        tree = audit.tree(owner["original"])
        node = tree.root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
        while node is not None and (node.start_byte, node.end_byte) != (owner["byte_start"], owner["byte_end"]):
            node = node.parent
        if node is None or node.type != owner["syntax"]:
            raise ValueError("Hanbo runtime flag owner has no exact complete AST boundary")
        bodies[role] = fragment
    actual = hanbo_runtime_flag_ast(audit.parser, bodies["ui_defaults"], bodies["ui_reducer"],
                                   bodies["mw_service"], bodies["mw_event"])
    if (bodies["ui_event"] != b'mt="MW_UPDATE_DEVICE_RUNTIMEDATA"' or
            bodies["ui_event_namespace"] != b"se=a(3254)"):
        raise ValueError("Hanbo UI and middleware runtime event identities differ")
    if flow.get("contract") != actual or audit.final_snapshot():
        raise ValueError("Hanbo runtime flag contract or original snapshot changed")
    return actual


def audit_hanbo_local_runtime(args):
    """Keep current mounted Hanbo controls and their actual local transports."""
    import host
    if args.family != "accessories" or args.function != "main" or args.product not in (None, [], [3893]):
        raise ValueError("hanbo-local-runtime requires the current 3893 main query")
    audit = host.HostLocalAudit()
    ui_set, ui_files = audit.source_set("accessories-3893-current")
    mw_set, mw_files = audit.source_set("accessories-mw-3893-current")
    ui = next(row for row in ui_files if Path(row["path"]).name == "main.a7630c14.js")
    css = next(row for row in ui_files if Path(row["path"]).name == "main.5b87dc95.css")
    chunk = next(row for row in mw_files if Path(row["path"]).name.startswith("6259."))
    main = next(row for row in mw_files if Path(row["path"]).name.startswith("main."))
    elsa = next(row for row in mw_files if Path(row["path"]).name.startswith("rzDeviceElsa."))
    roles, modules = {}, {}
    def owner(role, source, needle, kinds=None):
        keys = audit.retain(role, source, needle, kinds or {
            "variable_declarator", "function_declaration", "method_definition", "field_definition"})
        roles[role] = keys
        return keys
    for role, needle in {
        "ui_runtime_defaults": "BC={runtimeData:{cpuTemp:",
        "ui_runtime_reducer": "FC=(e,E)=>",
        "ui_thermal_ports_reducer": "DC=(e,E)=>",
        "ui_thermal_ports_update": "function CC(e,E,a){",
        "ui_ports_save_action": "GC=(e,E)=>",
        "ui_ports_action_state": "HC=(e,E,a)=>",
        "ui_ports_broadcast": "vC=(e,E)=>",
        "ui_firmware_warning": "function _g(){return(0,b.jsx)(\"div\",{className:JG",
        "ui_cooler_info": "fg=(0,F.connect)(e=>({isCelsius:",
        "ui_curve_editor": "function yg(e){let E=e.xAxis",
        "ui_fan_controls": "Yg=(0,F.connect)(e=>{var E,a;return{fanMode:",
        "ui_pump_controls": "Kg=(0,F.connect)(e=>{var E,a;return{pumpMode:",
        "ui_performance_root": "function xg(){",
        "ui_product_root": 'args:"getSpeedOfFanAndPumpTimer",device:"HANBO"',
        "ui_celsius_action": "type:se.Y6R,payload:{isCelsius:",
        "ui_temperature_unit": "Gg=e=>{let E=e.isCelsius",
    }.items():
        owner(role, ui, needle, {"class", "class_declaration"} if role == "ui_product_root" else None)
